insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 1, 'EGBEMA is charted on the 200,000 hour base. Month 3 recorded 4 events in 97230 hours. Which exposure units and which u does the engine return for that month?', '["4 units and a u of 8.227913, since one exposure unit on a u-chart stands for one recorded event in the month", "0.486150 units and a u of 2.893273, since every point on a u-chart is read at the pooled centre line of the year", "0.486150 units and a u of 8.227913, which is simply month 3''s own rate per 200,000 hours", "2.011750 units and a u of 2.982478, since the units of the chart''s first month are carried across all twelve points"]'::jsonb, 2, 'A month''s units are its hours over the base, 97230 over 200,000, which is 0.486150, and u is the count over the units, 8.227913: the month''s rate on the chosen base, rearranged. A unit is one base''s worth of hours and has nothing to do with the event count. The centre line of 2.893273 is the one reference every month is judged against, so it cannot also be month 3''s reading, and month 1''s 2.011750 units belong to month 1 alone.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 2, 'EGBEMA''s twelve months carry 63 events on 21.774650 exposure units, and the twelve monthly u values average 3.202958. Where does the engine draw the centre line?', '["At 2.893273, the sum of the counts over the sum of the units, so each month weighs in with its own exposure", "At 3.202958, the mean of the monthly u, so that each month carries an equal one twelfth share of the line whatever its hours", "At 2.893273, a figure the engine reaches by taking the median of the twelve monthly u values plotted on the chart", "At 2.389523, because the month that signals is taken out of the year before the engine draws the centre"]'::jsonb, 0, 'The method line reads ubar = sum(c) / sum(n): 63 over 21.774650 is 2.893273, sum then divide applied to months. The mean of the monthly u gives a thin month the same vote as a full one and is a different number. The median is not what the engine computes. 2.389523 is the revised centre with month 8 set aside, and a month is set aside only after an investigation finds a cause, never as a step in drawing the chart.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 3, 'Month 1 on EGBEMA has 2.011750 units and an upper limit of 6.491006. Month 3 has 0.486150 units and an upper limit of 10.211920. What makes month 3''s limit so much wider?', '["Its u is higher, and the engine widens each month''s limits in proportion to the reading that the month itself returned", "Its count is lower, and each month''s limit is the centre plus 3 times the square root of that month''s own count", "It falls early in the year, and the engine widens the first quarter''s limits while its centre line is still settling", "Its exposure units are fewer, and the distance from the centre to each limit is 3 times the square root of the centre over the month''s units"]'::jsonb, 3, 'The limits are ubar +/- 3 sqrt(ubar / n_i) with one centre for the whole chart, so only n moves them: fewer units, wider limits. A month''s own u plays no part in its limits, which is why month 3''s high reading can sit inside a wide band. Month 3''s count of 4 equals months 2, 9, 10 and 12, whose limits are far tighter. The centre is pooled over the whole year at once, so no month''s limits depend on where it falls in the calendar.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 4, 'On a u-chart with one pooled centre, month A carries four times the exposure units of month B. How does month A''s distance from the centre to its upper limit compare with month B''s?', '["It is a quarter of month B''s distance, because the distance shrinks in direct proportion to the units in the month", "It is half of month B''s distance, because that distance shrinks with the square root of the units", "It is the same as month B''s distance, because both months are measured from one pooled centre line for the year", "It is twice month B''s distance, because a month with more exposure is expected to carry more events around its mean"]'::jsonb, 1, 'The distance is 3 sqrt(ubar / n), so four times the units divides it by the square root of four, which is two. Under the Poisson count model the spread of a count grows with the square root of its mean, so the spread of the rate shrinks with the square root of the units, and the shrinkage is slower than in proportion. A shared centre fixes where the band is centred, and the width still follows each month''s own units. More events in absolute terms is a statement about the count; on the rate scale the band narrows.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 5, 'Every one of EGBEMA''s twelve lower control limits reads 0.000000 with `lclFloored` true. What should the monitoring note say about it?', '["That every month cleared its lower limit, which shows that incident reporting held steady on the site for the whole year", "That the raw lower limits were negative at this exposure, so this chart could only ever have found months that ran high", "That the lower half of the chart ran at a centre of zero, and only the upper limits carry the Poisson count model", "That no month recorded zero events, so the engine had no reason to test the low side of this particular chart"]'::jsonb, 1, 'Each raw lower limit, the centre minus 3 times the square root of the centre over the units, is negative on months of about 2 units, so the engine sets it to zero and flags it. A u cannot be strictly below zero, so no month could signal low, and the low side was never tested: a quiet low side says nothing about reporting. The centre and the Poisson count model are the same on both sides of the chart. The floor comes from the exposure, whatever the monthly counts happened to be.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 6, 'Month 8 on EGBEMA has 2.105450 units against a centre of 2.893273. Why is its raw lower control limit negative before the floor is applied?', '["Because month 8 signalled above, and the engine pushes a signalling month''s lower limit below zero to mark it out", "Because the engine subtracts month 8''s own u of 7.599326 from the centre, and that u is larger than the centre", "Because the lower limit is drawn from the mean of the monthly u, 3.202958, and month 8''s u sits well above it", "Because the centre of 2.893273 is smaller than 3 times the square root of the centre divided by 2.105450 units"]'::jsonb, 3, 'The raw lower limit is ubar minus 3 sqrt(ubar / n). At about 2 units the square root term times 3 is larger than 2.893273 itself, so the difference is negative, and it would stay negative whatever month 8 had recorded. A signal is read against the limits and never changes them. The month''s own u does not enter its limits, and the centre in every limit is the pooled 2.893273, never the mean of the monthly u.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 7, 'A monthly series is passed to `uChart` in which the second period has zero hours. What does the engine return?', '["A refusal naming `exposureHours[1]`, in the engine''s own words: exposureHours[1] is zero: a u-chart point needs exposure; drop periods with no hours before charting", "A chart with the second point returned as null and the other points drawn around a pooled centre, the way `pooledRate` treats a mothballed site", "A chart with the second point at a u of 0.000000 and a floored lower limit, since a period with no hours also has no events", "A refusal naming `counts`, because a period with no hours has no events to chart and the engine asks for its count to be removed"]'::jsonb, 0, 'A point''s units are its hours over the base, so zero hours give zero units, and both u and the limits divide by the units. The engine refuses, names the field and says what to do. `pooledRate` can pass over a period with no hours because it only sums, but a chart has to place every point it is given. The refusal that names `counts` is the other uChart refusal, for a series with no events at all.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 8, 'A site''s twelve months carry no recordables at all, and the series is passed to `uChart`. Why does the engine refuse it, and what does the course use instead?', '["Months with no events count as months with no exposure, so the engine refuses on the hours and asks for the periods to be dropped", "The chart would flag every month below, since each u of zero sits under its lower limit, so the engine declines to draw it", "The centre would be zero and every limit would have zero width; a zero count is read as an upper bound, as with the ABO crew''s 17.863823", "The engine will only draw a chart that has at least one signal on it, and a year without a single event cannot produce one"]'::jsonb, 2, 'The engine''s own words: counts are all zero: the centre line is zero and every limit has zero width. With no events the pooled centre is zero, the square root term is zero, and the band collapses. The Professional tier''s answer to a zero count is its interval: the ABO crew''s 0 recordables in 41300 hours still leave a 95 percent upper limit of 17.863823 per 200,000 hours. Hours are exposure whether or not anything happened. A u of zero on a lower limit of zero is not strictly below it, and the engine draws quiet charts routinely.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 9, 'EGBEMA is redrawn on the 1,000,000 hour base in place of the 200,000 hour base. What changes on the chart?', '["The centre moves to 3.202958, because a larger base changes how much weight each month carries in the pooled line", "Month 3 begins to signal, because the smaller units on the larger base tighten the limits relative to each month''s own u", "Nothing on the chart changes, because the engine converts every base back to 200,000 hours before it charts a series", "Every n shrinks and every u grows by the same factor, and the chart''s shape and its signals stay exactly as they were"]'::jsonb, 3, 'The count and the hours did not change; only the base did. Units scale down, u, the centre and every limit scale up by the same factor, so every point keeps its position relative to its limits and month 8 remains the only signal. The weights in the pooled centre are the units, and a common factor cancels out of them. The engine does not convert bases: it charts on the base the caller names, which is why the note must state it.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 10, 'EGBEMA''s mean of the monthly u is 3.202958 against a pooled centre of 2.893273. Which month does most to open that gap?', '["Month 3, whose u of 8.227913 rests on only 0.486150 units and still counts as one twelfth of the mean", "Month 8, the flagged month, because the engine sets a signalling month aside before it pools the centre line", "Month 11, whose u of 1.018563 is the lowest on the chart and drags the pooled centre down", "Month 1, whose 402350 hours make it the heaviest month in the mean of the monthly u, which weighs by hours"]'::jsonb, 0, 'In the pooled centre month 3 carries 0.486150 of 21.774650 units, a small share, while in the mean it carries one twelfth, and its reading is the highest on the chart. That mismatch of weights is what lifts the mean above the centre. Month 8 is in the centre as drawn; nothing is set aside until a cause is found. Month 11 has near-average exposure, so its weight barely differs between the two. The mean of the monthly u is unweighted, so hours play no part in it.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 11, 'Which EGBEMA month has the tightest limits on the chart, and why?', '["Month 11, whose 2 events are the fewest of the year, because each month''s limit is set by the count in that month", "Month 3, whose u of 8.227913 is the highest of the year, because the engine draws tighter limits around a high reading", "Month 8, with 421090 hours, the most on the chart, which gives it the smallest distance from the centre to its limit", "Every month shares a single pair of limits, because the centre line is pooled across the year and the base is fixed"]'::jsonb, 2, 'The limits depend on the centre and the month''s units only. Month 8''s 2.105450 units are the most on the chart, and its upper limit of 6.410039 is the lowest. Month 11''s count and month 3''s u do not enter their limits; month 3 in fact has the widest band, 10.211920, because it has the fewest hours. A pooled centre is shared by every month, and the limits still move with each month''s units.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 12, 'An analyst redraws EGBEMA with one flat upper limit, computed from the average month''s exposure, in place of the engine''s moving limits. What does that chart get wrong about month 3?', '["Nothing, because a flat limit and moving limits flag the same months on any chart that has a pooled centre line", "It puts month 3 over the line and hides that its reading rests on under a quarter of month 1''s hours", "It clears month 8, whose u of 7.599326 would sit under an upper limit drawn from the average month''s exposure", "It lowers the centre line, because the average month carries fewer events than the pooled year taken as a whole"]'::jsonb, 1, 'A limit from the average exposure is narrower than month 3''s own limit of 10.211920, so month 3''s u of 8.227913 crosses it, and the chart calls a thin month unusual without saying it is thin. The engine takes each month''s exposure because that is what keeps each limit honest about its own evidence. Month 8 sits well above any limit an average month produces. The centre is computed from counts and units whatever limits are drawn around it.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 13, 'Which model does the u-chart''s limit formula rest on, going by how the Expert tier explains the square root in it?', '["The Poisson count model, in which the spread of a month''s count grows with the square root of its mean", "A normal model of the twelve monthly rates, with its spread estimated from the scatter of the monthly u values", "A binomial model of the share of workers injured in a month, with the month''s headcount taken as the trials", "A model in which the spread of a month''s count grows in direct proportion to the count the month is expected to carry"]'::jsonb, 0, 'The square root term is the spread the Poisson count model expects for that month''s exposure, one sigma, and three of them each side is the Shewhart convention. The limits come from the centre and the units, so the scatter of the monthly readings is not used. The engine has no headcount input at all. A spread growing in proportion to the mean would make the band narrow in proportion to the units, and the formula narrows it with the square root of the units instead.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 14, 'Which inputs does `uChart` take, going by the engine''s own function table?', '["counts and exposureHours only, since a u-chart always runs on the 200,000 hour base and so has no base left to choose", "counts, exposureHours, base and confidence, since each month''s limits are a 95 percent interval on that month", "counts, headcount and base, since each month''s units are the people on site during the month divided by the base", "counts, exposureHours and base, with the base named by the caller exactly as for every other rate in the engine"]'::jsonb, 3, 'The function table lists counts, exposureHours, base, and the u-chart takes a named base for the same reason every rate in the engine does. The limits are 3 sigma limits from the method line and take no confidence input; confidence belongs to the interval and the comparison. Hours are the exposure, and the engine has no headcount input anywhere.'),
  ('safetystats', 'advanced', 'module', 'm01-the-u-chart', 15, 'EGBEMA''s month 5 has 1.859400 units and a u of 1.613424. Which reading of it follows from the engine''s method line, with its limits at ubar +/- 3 sqrt(ubar / n_i) and the lower limit floored at 0?', '["Its upper limit is 5.388087, which is what the method line gives at three sigma for a month of 1.859400 units", "Its upper limit is 6.635494, and it signals below because its u is under the chart''s centre line of 2.893273", "Its upper limit is 6.635494 and its lower limit is floored at zero, so month 5 sits inside its limits", "Its upper limit is 6.491006, month 1''s limit, since every month shares one pooled centre"]'::jsonb, 2, 'Month 5''s printed limits are 0.000000 and 6.635494, and 1.613424 lies between them, so its signal is null. 5.388087 is month 5''s derived 2 sigma limit, a narrower band than the engine draws. Sitting below the centre is ordinary; a low signal needs a u strictly below the lower limit, and here that limit is zero. A shared centre does not give a shared limit, because each month''s units set its own band.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 1, 'In the golden case uchart-points-on-the-limits, point 1 recorded 18 events, its u is 2.000000 and its upper limit is 2.000000. What does the engine return as its signal?', '["above, because a u equal to the upper limit is treated as reaching it, and reaching the limit is a signal", "null, because a point sitting exactly on its limit is inside the band under the strict rule", "above, because the engine rounds a tie on a limit toward the investigation so that no real change is missed", "below, because a point on its upper limit is read against the lower limit of 0.000000 when the two are tied"]'::jsonb, 1, 'The golden''s note: under the strict rule (Montgomery: a point OUTSIDE the limits) neither signals. Only a u strictly greater than the upper limit, or strictly less than the lower, earns above or below. The engine has no tie-breaking toward a flag, and the lower limit plays no part for a point on its upper limit.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 2, 'Point 2 of the same golden case recorded 0 events: its u is 0.000000 and its lower limit is 0.000000. Why does it not signal below?', '["Because the engine never tests the low side of any chart, whatever the exposure behind each of the points", "Because a count of 0 is refused by `uChart`, so the point is left off the chart and carries no signal at all", "Because the lower limit is floored, and a floored limit switches the low-side test off for that one point on the chart only", "Because zero is not strictly below a lower limit of zero, and the engine''s rule needs a point strictly outside"]'::jsonb, 3, 'u equals the lower limit, so the point is on the line and inside the band. The engine does test the low side, and the golden low-point case signals below on a positive limit. A zero count in one period is charted normally; only a chart whose counts are all zero is refused. The rule is the same strict comparison on every point; on this golden case ubar is 1 and n is 9, so the limits are exactly 0 and 2.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 3, 'EGBEMA''s chart returns `outOfControl` as [7]. Which month does the monitoring note name as the signal?', '["Month 8, because the list holds zero-based indices and the note numbers months starting from 1", "Month 7, because the list holds the month number exactly as it would be printed in the note", "Months 1 to 7, because the list gives the count of months that sit outside their control limits", "Month 7 and month 8, because an index in the list marks the boundary between two adjacent months"]'::jsonb, 0, 'The engine''s list is zero-based, so index 7 is the eighth month, and month 8 is the one whose u of 7.599326 sits above its limit of 6.410039. Month 7''s u of 2.509599 is well inside its limit. The list names indices, one per signalling point, and a list of one entry is one signal.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 4, 'On EGBEMA, how many months sit above their upper limit when the limits are drawn at 2 sigma in place of the engine''s 3 sigma, and which are they?', '["1 month, month 8, since narrowing the band does not change which months sit outside it", "2 months, month 8 and month 1, since month 1 has the second largest count on the chart", "2 months, month 3 against 7.772371 and month 8 against 5.237783", "3 months, months 3, 4 and 8, the three months whose u lies above the centre of 2.893273"]'::jsonb, 2, 'At 2 sigma, derived, month 3''s u of 8.227913 clears 7.772371 and month 8''s 7.599326 clears 5.237783. Every other month stays inside: month 1 reads 2.982478 against 5.291761 and month 4 reads 3.373705 against 5.687703. A narrower band flags more months, and a u above the centre line is ordinary; a count carries no signal of its own until it is set against the month''s units.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 5, 'The Expert tier weighs 3 sigma against a narrower band. What is the main cost of drawing EGBEMA''s limits at 2 sigma?', '["None to speak of, since a narrower band finds every real change sooner and each extra flag is a real change on site", "More flags, each one an investigation, and on a stable process most of the extra flags are months that were only unlucky", "A higher centre line, because the 2 sigma chart pools the year differently and lifts the reference that months meet", "Fewer flags on the thin months, since a 2 sigma band is wider than a 3 sigma one wherever the exposure is small"]'::jsonb, 1, 'Every flag sends someone to pull records and interview supervisors, and a team that chases flags and finds nothing learns to stop reading the chart. A narrower band does see more, as month 3 shows, but most extra flags on a stable process are chance. The centre is the pooled 2.893273 whatever band is drawn. A 2 sigma band is narrower than a 3 sigma one at every exposure.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 6, 'An analyst looks at EGBEMA, sees month 3 sitting inside its 3 sigma limit, and redraws at 2 sigma so that it flags. What is wrong with that?', '["Nothing, because a 2 sigma band is always the better choice on a chart with fewer than twenty monthly points to read", "Nothing, because the engine accepts a sigma input and the analyst has simply used the setting that the data suggested", "Only the arithmetic, because month 3''s u of 8.227913 is actually below its 2 sigma limit of 7.772371 on EGBEMA", "The band was chosen after looking, to produce the flag; a band decision belongs in the note with its reason, made in advance"]'::jsonb, 3, 'Narrowing a band can be defended for a stated reason decided in advance: a high-hazard operation, a known recent change, a regulator''s request. Narrowing it after seeing the chart chooses the band to make the flag. The engine has no sigma input and always draws 3 sigma. Month 3''s 8.227913 is above 7.772371, so the arithmetic is right and the reasoning is what fails.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 7, 'Which sigma setting does the engine let a caller pass to `uChart`?', '["Any whole number of sigma through the chart''s confidence field, which takes 2 or 3 as its usual values", "3 by default and 2 on request, through a `sigma` field that the chart''s result echoes in its basis block", "None: the engine has no sigma input, and every chart it draws is a 3 sigma chart as its method line states", "The number of sigma implied by the base, which is 3 on the 200,000 hour base and 2 on the million base"]'::jsonb, 2, 'The method line fixes it: limits ubar +/- 3 sqrt(ubar / n_i). uChart takes counts, exposureHours and base and nothing else. The 2 sigma column the course prints is derived for teaching, outside the engine. Changing the base rescales everything by one factor and leaves the chart''s shape alone.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 8, 'In the golden case uchart-positive-lcl-with-a-low-point, point 4 recorded 0 events in 4800000 hours against a lower limit of 0.920345. What does the golden''s note say the signal is worth investigating as?', '["Under-reporting, because a month with 0 events in 4.8 million hours falls below its lower limit", "A real improvement on site, since a month with no events is the result every safety programme is aiming at", "A data entry error in the hours, since the other points carry 4700000 to 6100000 hours and point 4 is in range", "Nothing, since a low point on a u-chart is noted for the record but only a high point counts as a real signal"]'::jsonb, 0, 'The golden''s note reads: a month with 0 events in 4.8 million hours falls below its lower limit (a signal worth investigating as under-reporting). A fall in the rate with no change in the work is the signature of a change in counting, so the counting is the first place to look. Celebrating the zero skips that question. Point 4''s hours sit inside the range of the others, so the hours are not what stands out. The rule is symmetric: strictly below the lower limit is a signal.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 9, 'Why can the golden low-point chart signal below when EGBEMA never can?', '["Its centre line is the mean of the u values, which lifts the lower limits clear of zero on every one of its points", "Its lower limits are left unfloored, so they may run negative and a point at zero can fall beneath them", "It is drawn at 2 sigma, which gives a positive lower limit wherever the 3 sigma limit would have been floored", "Its points carry millions of hours, so the square root term is small and every lower limit stays above zero"]'::jsonb, 3, 'On 4700000 to 6100000 hours the units are large, 3 sqrt(ubar / n) is small, and the centre minus it stays positive, 0.911835 to 1.011164. EGBEMA''s months of about 2 units push the raw lower limit below zero. Both charts use the pooled centre, the same floor and the same 3 sigma rule; the difference is the exposure in each point.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 10, 'On the golden low-point chart, point 3 has 6100000 hours and point 4 has 4800000 hours. Which one carries the higher lower limit?', '["Point 4, at 0.920345, since a point with no events is given a higher floor to make its signal visible", "Point 3, at 1.011164, since more hours in a point give a narrower band around the same centre", "Neither, since both are measured from one pooled centre and share a lower limit of 0.936592", "Point 4, since fewer hours mean fewer expected events and so a lower limit lying closer to the centre"]'::jsonb, 1, 'More units shrink the distance from the centre, lifting the lower limit and lowering the upper: point 3 reads 1.011164 and 2.437872. Point 4''s 0.920345 is lower because its hours are fewer. The engine does nothing special for a point with no events. 0.936592 is the limit of points 1 and 7, which carry 5000000 hours each; a shared centre does not give a shared limit.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 11, 'In the golden case uchart-small-exposure-wide-limits, point 1 recorded 3 events in 2000 hours: a u of 300.000000 against an upper limit of 44.196051. What does the case show?', '["A point on 2000 hours can never signal, because the engine widens a thin point''s limit past any reading", "Point 1 is quiet, because on thin exposure the engine compares the raw count, 3, with the upper limit", "Wide limits do not stop a thin point signalling: point 1 still clears its limit and signals above", "Point 1 signals only because its hours are below the base, which the engine reads as a fault"]'::jsonb, 2, 'The limit scales with 1/sqrt(n_i), so 2000 hours give a wide band, 44.196051, and a u of 300.000000 still clears it. Several cases in a few days on a small crew is worth a look whatever the exposure. The engine compares u with the limit on every point, and hours below the base are ordinary data that give a unit count below 1.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 12, 'On the same small-exposure golden case, point 2 recorded 0 events in 2000 hours and does not signal. What is the fair reading of point 2?', '["The chart cannot tell a thin quiet period from a lucky one, so its silence says little about that crew", "The crew on point 2 has shown a rate of zero, which the chart confirms by leaving the point unflagged", "The crew on point 2 is safer than the crew on point 3, which recorded 1 event on 400000 hours of work", "Point 2 should have signalled below, and the engine missed it because its lower limit was set far too high"]'::jsonb, 0, 'On 2000 hours the band is wide and the floored lower limit is zero, so no count on that point could signal low and a zero reads as nothing unusual. A zero on thin exposure is a weak measurement; the Professional tier''s zero-count interval shows how high a rate it still allows. Point 3''s 400000 hours make its 0.500000 a far better measured rate. A u of zero cannot be strictly below a lower limit of zero.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 13, 'EGBEMA''s highest u is month 3''s 8.227913, yet the only signal is month 8 at 7.599326. Why does the lower reading signal and the higher one not?', '["Month 8''s count of 16 is the largest on the chart, and the engine flags whichever month carries the largest count", "Month 3 falls before the intervention in month 7, and the engine only tests the months that come after it", "Month 3 was set aside as a thin month before the limits were drawn, so its reading is never tested at all", "Month 8''s 421090 hours give it a limit of 6.410039, while month 3''s 97230 hours give it a limit of 10.211920"]'::jsonb, 3, 'Each month is judged against its own limit, set by its units. Month 3''s u rests on 0.486150 units and sits under a wide band; month 8''s rests on 2.105450 units and clears a tight one. The engine reads u against the limit and never ranks counts. uChart has no intervention input, and nothing is set aside when a chart is drawn.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 14, 'Month 8 has 2.105450 units and an upper limit of 6.410039. What is the largest whole number of events month 8 could have recorded and not signalled?', '["6, since the expected count at the centre is about 6 and any count above the expected count would signal", "13, since 2.105450 times 6.410039 is just under thirteen and a half, and a signal needs a u strictly above the limit", "16, since the month''s own count is the largest a month can record without crossing its upper control limit", "14, since a count of 14 on 2.105450 units gives a u that sits exactly on the limit and so does not signal"]'::jsonb, 1, 'The count on the limit is the limit times the units, which is just under thirteen and a half. At 13 events u is below 6.410039; at 14 it is above it and signals. Redrawn in the panel, the changed count also moves the pooled centre and the limit a little, and the answer is still 13. The expected count of 6.091641 is the centre, and ordinary months scatter well above it without a signal. Month 8 signalled with 16, so 16 is past the limit. No whole count sits exactly on this limit.'),
  ('safetystats', 'advanced', 'module', 'm02-signals', 15, 'A month with no recordables in it falls strictly below a positive lower limit. How does the Expert tier say the note should treat it?', '["As good news to be reported without investigation, since a low signal can only mean a safer month", "As noise to be safely ignored, since the engine''s signal rule is applied to high months and low ones alike", "As a signal like any other, asking what was different, with the counting as the first place to look", "As a reason to set the month aside at once, since a zero count is not a real observation"]'::jsonb, 2, 'The rule is symmetric: strictly below the lower limit is a signal in the same sense as strictly above the upper one, and it asks the same question. For a low point the counting comes first, because a fall with no change in the work is the signature of under-reporting. The same symmetric rule is exactly why the point must be investigated. A zero is a real observation, and a month is set aside only on a found cause.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 1, 'EGBEMA''s month 8 signals above: a u of 7.599326 against a limit of 6.410039. What does the signal by itself establish?', '["That something on site caused the excess in month 8, and the investigation''s job is only to put a name to that cause", "That the intervention which started in month 7 failed, since the first signal after it arrived only one month later", "That month 8 must be set aside and the chart redrawn, since a signalling month cannot stay in a pooled centre line", "That the month''s reading is further from the centre than ordinary variation at its exposure explains, which is a reason to go and look"]'::jsonb, 3, 'A signal is a statement about the numbers and the engine stops there: its result carries no cause field. It asks what was different about month 8, and the investigation may or may not find an assignable cause. A high month after an intervention does not by itself show the intervention failed. Setting a month aside needs a found cause, never the signal alone.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 2, 'At EGBEMA''s centre line of 2.893273, what count would a month with month 8''s 2.105450 units be expected to carry?', '["6.091641 events, the centre times the month''s units", "16 events, since the expected count of a month is the count it actually recorded", "7.599326 events, the month''s own u read as a count for that month''s exposure", "2.893273 events, since the centre line is itself the expected count of each month"]'::jsonb, 0, 'The expected count at the centre is the centre times the units, 2.893273 times 2.105450, printed as 6.091641. Month 8 recorded 16, far above it. u is a rate per 200,000 hours and becomes a count only when multiplied by the units, and the centre is a rate in the same way.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 3, 'An investigation into month 8 finds that its 421090 hours were understated in the timesheet export. What has the signal turned out to flag?', '["A real rise in harm on site, since the count of 16 events is unaffected by any error in the hours", "Under-reporting of events, since understated hours are the usual sign that cases were left off the register", "A data error in the denominator: with the true hours the month''s rate is lower than the chart showed", "Nothing that matters, since an error in the hours changes the units and leaves the month''s u where it was"]'::jsonb, 2, 'u is the count over the units, and the units are the hours over the base, so understated hours make the units too small and u too high. The investigation''s families of cause include the hours being wrong, and then the chart has flagged a data error. The count is unchanged, but the rate is what the chart judges. Understated hours inflate a rate, which is the opposite direction to under-reporting.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 4, 'EGBEMA is redrawn with month 8 set aside. Which result does the engine return for the revised chart?', '["11 months, a centre of 2.893273, and no month flagged, since the centre was fixed when the chart was first drawn", "11 months, a centre of 2.389523, and no month flagged", "12 months, a centre of 2.389523, and month 3 flagged, since month 8 is kept at the centre''s value in its place", "11 months, a centre of 2.389523, and month 3 flagged, since tighter limits always push the thin month over the line"]'::jsonb, 1, 'Removing month 8 takes its 16 events and 2.105450 units out of the totals, and the pooled centre falls from 2.893273 to 2.389523; the revised chart flags nothing. The centre is recomputed from what remains, so it moves. A set-aside month is removed and nothing takes its place. Tighter limits can bring a new flag, which is why the redrawn chart must be read again, but on EGBEMA none appears.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 5, 'Under what condition may month 8 be set aside and the chart redrawn?', '["When month 8 signals above its upper limit, since a signalling month is outside the ordinary process", "When month 8''s count is the largest on the chart, since the largest month always distorts a centre line pooled on it", "When removing month 8 leaves a chart with no signals on it, which confirms that month 8 did not belong with the rest", "When an investigation has found an assignable cause for month 8, identified and recorded, that explains its excess"]'::jsonb, 3, 'Setting a month aside needs a found cause; setting it aside because it is high is removing the data that disagree. A signal only asks the question. The size of a count proves nothing about a cause. A revised chart that comes out clean is what removing any high month produces, so it cannot be the evidence for removing it.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 6, 'Two analysts each redraw EGBEMA without month 8. One had a recorded cause; the other removed it because it was high. How can a reader tell the two revised charts apart?', '["Only by the note beside the chart, which states the cause and how it was confirmed; both charts show 2.389523", "By the centre line, since a chart revised without a cause is drawn by the engine around the mean of the monthly u", "By the flags, since the engine marks a month removed without a cause as a signal on the redrawn chart", "By the months list, since the engine refuses to set a month aside unless a cause is passed in its own input field"]'::jsonb, 0, 'The difference is invisible on the redrawn chart: both give the same centre of 2.389523. A revised chart with no stated cause should be read as the drawn one with a month deleted. The engine draws what it is given; it has no cause input and no way to know why a month is missing, so it neither changes the centre rule nor flags the absence.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 7, 'EGBEMA''s chart has been revised after a found cause for month 8. Why does the Expert tier say the revised chart must be read again from the start?', '["The engine swaps the base on a revised chart, so every figure on it has to be restated on the 200,000 hour base", "The revised chart keeps the drawn chart''s limits and moves only its centre, so each month must be checked by hand", "Every limit comes down with the lower centre, so a month quiet on the drawn chart could fall outside its revised limit", "The revised chart will flag month 3 whatever its data, because removing a full month always exposes the thin one"]'::jsonb, 2, 'Every limit is measured from the centre, and the centre falls from 2.893273 to 2.389523, so the limits tighten and the first chart''s clean bill of health does not carry over. On EGBEMA the revised chart flags nothing, which is a result the engine returned and the note quotes. The base is the caller''s and does not change. Limits move with the centre. Nothing forces month 3 over its line.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 8, 'Month 8 is set aside on a found cause. A year later the same cause recurs. What does that do to the revision?', '["Nothing, since a revision is final once the cause has been recorded and the chart has been redrawn", "It undoes it: a cause that recurs was never a one-off, and the month belongs back in the centre", "It justifies setting aside the new month unexamined, since the cause is already on file from month 8", "It shows the intervention in month 7 failed, since the cause survived the change it made on site"]'::jsonb, 1, 'Revision is a claim, and it has to be tracked as one. The revised centre is the better description of the ordinary process only if the cause was a one-off. A cause that recurs is part of the process, so the months it produced belong in the centre, and setting aside each new occurrence, least of all without investigating it, would keep deleting the process from its own chart. A recurring cause says nothing on its own about the intervention.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 9, 'Month 8''s excess is traced to a single event with several injured workers. While the file is open, the analyst proposes setting aside months 3 and 4 as well, since both read above the centre. What does the Expert tier say?', '["Set aside all three, since removing every month above the centre gives the cleanest statement of the process", "Set aside month 3 only, since it is the highest u on the chart and its thin exposure makes it unreliable as data", "Set aside none of them, since a single event with several injured workers is never an assignable cause", "Set aside only the month the cause explains; one found cause in month 8 is no licence to remove months 3 and 4"]'::jsonb, 3, 'One cause, one month. The cause found for month 8 explains month 8. Removing months because they are high, or thin, is removing the data that disagree, and month 3''s thin exposure is exactly what its wide limit already accounts for. A single event with several injured people is one of the counting changes the tier lists as a possible cause.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 10, 'Month 3 reads 8.227913, the highest u on EGBEMA, and does not signal. How should the monitoring note treat that quiet month?', '["As a weak reassurance: on 97230 hours the chart needed a reading above 10.211920 before it could say anything", "As a clean result, since a month inside its limits has been shown by the chart to be an ordinary month for the site", "As a hidden signal, since the highest u on a chart is the month that ought to be flagged on any chart", "As bad data, since a month with under a quarter of the usual hours should be removed before charting"]'::jsonb, 0, 'A point inside its limits means the chart cannot distinguish that month from the ordinary process at that exposure. Month 3 had 4 events on 0.486150 units, and a real rise in a month that thin could easily stay quiet. Each month is judged against its own limit, and a thin month is legitimate data; the remedy, if many points are thin, is a coarser grain stated in advance.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 11, 'The Professional tier printed the exposure at which zero events bring the 95 percent upper limit down to 2.000000 per 200,000 hours. Why does the Expert tier recall it beside month 3''s 97230 hours?', '["Because 97230 hours are enough for zero events to rule out a rate above 2.000000, which makes month 3''s quiet a result", "Because the table shows the u-chart and the interval disagree about month 3, and the interval is the one to trust", "Because 368887.945411 hours are needed even for that bound, and month 3 sits far below it, so its quiet cannot show much", "Because month 3''s upper limit of 10.211920 is the zero-event bound at 97230 hours, read off the same table row"]'::jsonb, 2, 'Zero is still a measurement: it bounds the rate from above, and on few hours the bound is high. The table needs 368887.945411 hours before zero events cap the rate at 2.000000, and month 3 had 97230. The chart and the interval make the same point from two sides. The control limit is ubar plus 3 sqrt(ubar / n), a different construction from the zero-event bound.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 12, 'EGBEMA''s intervention started in month 7. With every month in, what does the before-and-after comparison return?', '["A rate ratio of 0.677882, a 95 percent interval of 0.357764 to 1.257771, and a p-value of 0.241552", "A rate ratio of 1.028627, a 95 percent interval of 0.607952 to 1.755328, and a central p-value of 1.000000", "A rate ratio of 1.028627 with a central p-value of 1.015454, twice the smaller tail as the engine reports it", "A rate ratio of 1.028627, and an interval that excludes 1, so the after period is shown to be worse than before"]'::jsonb, 1, 'After: 35 events in 2389010 hours; before: 28 in 1965920. The engine returns 1.028627, 0.607952 to 1.755328, and 1.000000. The 0.677882 row is the one with month 8 set aside. Twice the smaller tail is a derived 1.015454, and the engine caps the central p-value at 1. The interval runs from 0.607952 to 1.755328, which includes 1.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 13, 'The before-and-after comparison with month 8 set aside reads 0.677882, p-value 0.241552. When may that row be the one the note leads with?', '["Always, since month 8 is the flagged month and a flagged month is removed from any comparison drawn across it", "Whenever it gives the lower ratio, since the programme deserves the comparison that shows its real effect most clearly", "Whenever its p-value is the smaller of the two, since the smaller p-value marks the more informative comparison", "Only if an investigation found a cause for month 8, and that cause had nothing to do with the intervention itself"]'::jsonb, 3, 'Month 8 falls after the intervention, so removing it can only improve the after rate: the second row flatters the programme. It is admissible only on a found cause, and if month 8''s excess came from the very work the intervention changed, it belongs in the after period. A signal is not a cause. Picking the row by its ratio or its p-value is choosing the result first. Without a found cause the all-months row is the comparison.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 14, 'Taking both before-and-after rows on EGBEMA together, which statement does the tier support?', '["The intervention worked, since one of the two rows shows the after rate at about two thirds of the rate before it began", "The intervention failed, since with every month in the after rate is higher than the before rate on the chart", "Neither row is significant at 0.05: both intervals include 1, and the data cannot say the rate changed either way", "The rates before and after are equal, since a p-value above 0.05 shows that the intervention changed nothing"]'::jsonb, 2, 'One month turns the ratio from above 1 to below it, and neither comparison is significant. The favourable row is admissible only with a found cause, and even then its interval, 0.357764 to 1.257771, includes 1. A ratio of 1.028627 with an interval to 1.755328 is no evidence of harm either. A p-value above 0.05 says the data cannot tell; the all-months interval runs from 0.607952 to 1.755328, so large effects in both directions remain possible.'),
  ('safetystats', 'advanced', 'module', 'm03-what-a-signal-means', 15, 'What must a before-and-after claim on a u-chart state, at minimum, according to the Expert tier?', '["The rate ratio after over before, since the ratio carries the whole of the finding and the rest is working that can be left out", "The start month, the months in each period, any month set aside with its cause, the counts and hours, and the ratio, interval and p-value", "The p-value alone, since a reader needs to know only whether the change was significant at 0.05 to judge the programme", "The after rate and the target rate, since the claim is about whether the programme brought the site under its target"]'::jsonb, 1, 'A before-and-after claim has to say which months it used and why. A reader given only 0.677882 has been handed the favourable half of the table; a reader given both rows, with the reason month 8 was or was not set aside, can judge the claim. The ratio needs its interval, the p-value needs its months, and a target is not part of the comparison.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 1, 'IOGP''s 2024 TRIR rests on 3071 recordable cases in 3795000000 hours. The engine returns 0.809223 per 1,000,000 hours and IOGP prints 0.81. How much of the engine''s figure can a benchmark comparison lean on?', '["All six decimals, since the engine reproduces the golden with a relative difference of 0 on this row", "Only the first decimal, since IOGP rounds its published rates to one place before they reach the engine", "Down to about its third decimal, because the hours are printed to the nearest million and half a million moves the fourth", "None of it, since a figure the engine recomputes from published inputs cannot then be quoted beside a published rate at all"]'::jsonb, 2, 'The IOGP report prints the TRIR hours to the nearest million, and half a million hours either way moves the rate in its fourth decimal, so 0.809223 is exact for the hours as printed and good to about one unit in the fourth decimal for the hours as worked. A relative difference of 0 against the golden shows the arithmetic matches the golden, which carries the same rounded hours. IOGP prints 0.81, two decimals. Quote IOGP''s 0.81 as the published figure and carry 0.809223 through the arithmetic, labelled as such.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 2, 'In 2024 IOGP recorded 32 fatalities in 21 fatal incidents on 4158877000 hours. Which pair of rates per 100,000,000 hours do those counts give?', '["An observed FAR of 0.769438 from the fatalities and a fatal incident rate of 0.504944 from the incidents", "An observed FAR of 0.504944 from the incidents, since the FAR counts each fatal event once whatever its toll", "An observed FAR of 0.769438 from both counts, since IOGP adds fatalities and fatal incidents into one rate", "An observed FAR of 0.820324, since the 2024 FAR is always quoted on the prior year''s hours by IOGP convention"]'::jsonb, 0, 'The FAR counts fatalities, so an incident that kills several people moves it by several and the incident rate by one: 32 gives 0.769438 and 21 gives 0.504944 on the same hours. The two counts are kept separate, and a benchmark comparison must say which it uses. 0.820324 is the 2023 observed FAR, 27 fatalities on 2023''s own 3291382000 hours.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 3, 'UGHELLI''s recordable rate is 0.776317 per 200,000 hours; the IOGP 2024 TRIR is 0.809223 per 1,000,000 hours. What does the honest comparison show?', '["UGHELLI''s rate is below the industry''s, since 0.776317 is smaller than the IOGP figure of 0.809223", "The two rates are about the same, since 0.776317 and 0.809223 differ in their second decimal only", "UGHELLI sits a few percent under the industry, since 0.776317 against 0.809223 is a small gap in the site''s favour", "On the IOGP base UGHELLI reads 3.881586, which is 4.796684 times the IOGP figure"]'::jsonb, 3, 'The base must match first. The count and the hours do not change when the base does, so UGHELLI''s rate on the million-hour base is 5 times its OSHA figure, 3.881586, and set against IOGP''s 0.809223 it is 4.796684 times the industry figure. Comparing across the two bases is off by a factor of five, in the flattering direction for whoever quotes the smaller base.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 4, 'UGHELLI and IOGP are now both on the million-hour base. What must still be checked before the ratio of 4.796684 means anything?', '["Nothing further, since a shared base is the one condition a benchmark comparison needs before the ratio can be read", "That the case classes match IOGP''s TRIR, which counts fatalities, lost workday, restricted workday and medical treatment cases", "That UGHELLI''s hours were counted to the nearest million, so its rounding matches the rounding of IOGP''s hours", "That UGHELLI had at least 32 recordables, the count under IOGP''s 2024 FAR, so both rates rest on similar counts"]'::jsonb, 1, 'A shared base is necessary and not sufficient: the definition and the workforce must match too, both contractor and company in or both out. The engine takes a count that arrives classified and cannot check the name printed beside it, so the definition check is a reading exercise. Rounding UGHELLI''s hours to a million would destroy the figure. The FAR''s count is irrelevant to a recordable rate.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 5, 'Run through the engine as if the IOGP 2024 total were a second workforce, UGHELLI reads a rate ratio of 4.796684 with a 95 percent interval of 2.191251 to 9.117590. Whose uncertainty does that interval mostly carry?', '["UGHELLI''s, because its rate rests on 9 events while the IOGP total rests on 3071", "IOGP''s, because its total spans billions of hours pooled across many companies and years", "Both equally, because the conditional exact test splits the uncertainty evenly between the groups", "Neither, because a rate ratio against a published figure is exact and carries no uncertainty"]'::jsonb, 0, 'On the conditional exact test the IOGP rate, resting on 3071 events, behaves almost like a known constant; UGHELLI''s 9 events make the interval wide. Its upper limit over its lower is of the same order as the Professional tier''s ladder at a handful of events. Narrowing it takes more UGHELLI exposure; more IOGP hours would change almost nothing. The ratio is an estimate from counts and carries their uncertainty.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 6, 'The UGHELLI against IOGP comparison returns a central p-value of 0.000301. What does the Expert tier say that p-value tells you?', '["That UGHELLI''s workforce is proven worse than every IOGP company at the 0.000301 level, since the test compares the site with each of them", "That the two rates are equal, since a p-value below 0.05 means the test found no evidence of a difference between the two groups", "Little: it tests whether UGHELLI shares one pooled rate with all of IOGP, which nobody expected, so the ratio and its interval carry the information", "That the comparison is unreliable, since the engine refuses a p-value when one group''s hours are over a thousand times the other''s"]'::jsonb, 2, 'The test treats the IOGP total as one workforce under one rate; it is many workforces under many. Nobody expects a single site to share the pooled rate exactly, so a small p-value answers a question that was never in doubt. The information is in the ratio, 4.796684, and its interval, whose lower limit of 2.191251 is above 1. The test knows nothing of individual companies. A p-value below 0.05 is the opposite of no evidence, and the engine runs the comparison without complaint.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 7, 'An analyst wants a narrower interval on UGHELLI''s ratio to the IOGP 2024 TRIR. What would narrow it?', '["More IOGP hours, since the reference total is the larger of the two groups and dominates the test", "A move to the 200,000 hour base, since it shrinks both limits by a factor of five", "A 90 percent confidence level quoted as 95 percent, since the two intervals differ only slightly", "More UGHELLI exposure, since the interval''s width comes almost entirely from UGHELLI''s 9 events"]'::jsonb, 3, 'The IOGP rate behaves nearly like a constant on 3071 events, so more IOGP hours would change almost nothing; UGHELLI''s count is where the uncertainty lives. A rate ratio has no base in it, since the base cancels. Quoting a 90 percent interval as 95 percent misstates it; a lower confidence level is a real choice that must be stated as such.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 8, 'A site manager asks where UGHELLI ranks among IOGP''s member companies. What can the engine''s comparison support?', '["A ranking in the top tenth of member companies, since the lower limit of the rate ratio, 2.191251, is well above 1", "No ranking: placing a site in a percentile needs the distribution of company rates, which the pooled IOGP figure does not carry", "A ranking in the bottom half, since a p-value of 0.000301 places UGHELLI in the worst 0.000301 share of companies", "A ranking at the median, since the pooled IOGP rate is by construction the rate of the median member company"]'::jsonb, 1, 'The IOGP figure pools companies; it is a reference line with no distribution behind it in the engine, which carries no benchmark rates at all. The ratio''s interval says UGHELLI''s gap to the pooled figure is larger than its own count uncertainty, and nothing about other companies. A p-value is not a percentile. A pooled rate is the rate of the whole membership, generally different from the median company''s.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 9, 'Where do the IOGP counts and hours used in this module come from?', '["From a benchmark table exported by the engine, which ships IOGP''s rates so that a caller can compare a site", "From the engine''s `RATE_BASES` export, which pairs each named base with the IOGP rate last published on that base", "From the vendored golden, where they sit as published inputs; the engine carries no benchmark rates of its own", "From the capstone''s own inputs, which supply each year''s IOGP figures for the benchmark part of the course"]'::jsonb, 2, 'The course says so: the engine carries no benchmark rates, and the IOGP figures come from the vendored golden, where they are published inputs; the engine recomputes each rate from them and matches the golden with a relative difference of 0. `RATE_BASES` holds three bases and nothing else. The capstone''s workplaces are separate and are never a source of teaching figures.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 10, 'IOGP''s five-year observed FAR for 2020 to 2024 is 0.826095 by sum then divide, and the mean of the five yearly rates is 0.833228. Which should a report quote, and why?', '["0.833228, because each year is a report and every report deserves an equal fifth of the weight", "0.826095, because IOGP computes its own five-year figure as the sum of fatalities over the sum of hours", "0.833228, because the mean of the yearly rates removes the effect of the membership''s hours growing", "Either one, because the two methods agree on any five-year series and differ only by rounding in the last places"]'::jsonb, 1, 'IOGP pools, and the engine reproduces its 0.826095 exactly, as a pooled rate and as one rolling window of 5 years. The mean of the yearly rates weights 2022''s 2579000000 hours like 2024''s 4158877000 and is a different number; averaging IOGP''s rates is the mean-of-rates mistake at industry scale. The two methods differ by construction: the gap between 0.826095 and 0.833228 comes from the weighting, and rounding plays no part in it.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 11, 'The observed FAR fell from 0.820324 in 2023 to 0.769438 in 2024. The 2024 FAR''s 95 percent interval runs from 0.526295 to 1.086218. What does that interval say about the fall?', '["It is a real improvement, since the 2024 rate is lower and it rests on more hours than the 2023 rate did", "It is a real improvement, since 0.769438 is below 0.820324 and both figures reproduce IOGP''s published rates", "It cannot be judged at all, since an interval on an observed FAR is only defined for the five-year pooled figure", "It is smaller than 32 fatalities can resolve: the 2023 figure sits inside the 2024 interval, so the fall sits within the count''s own scatter"]'::jsonb, 3, 'A single year''s observed FAR rests on a few dozen fatalities. 0.820324 lies between 0.526295 and 1.086218, so the 2024 data are consistent with the 2023 rate, and a headline calling the fall an improvement is reading scatter. More hours do not remove the uncertainty of a small count. Matching the published figure says the arithmetic is right. Any single year''s FAR has its own exact interval.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 12, 'What does IOGP''s five-year pooled observed FAR of 0.826095 hide that the yearly figures show?', '["The 2022 peak of 1.279566, which the five-year figure dilutes among the years around it", "Nothing, since the pooled figure carries the same information as the five yearly rates together", "The fall in hours after 2020, which the pooled figure removes by weighting every year by one fifth", "The 2020 figure of 0.550271, which sum then divide drops as an incomplete year"]'::jsonb, 0, 'A five-year figure is steady because it pools, and the price is that a real change shows only slowly, diluted by the years before it. The 2022 peak is visible in the yearly column and invisible in 0.826095. Pooling weights each year by its hours, and the hours grew from 2544201000 in 2020 to 4158877000 in 2024. Every year is in the pooled figure.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 13, 'The UGHELLI against IOGP comparison reports an expectedProportion of 0.000611. What is that figure?', '["UGHELLI''s events as a share of all the events in the comparison, which is its 9 over the events counted in the two groups taken together", "The chance that a rate ratio as large as 4.796684 would appear by chance alone, which is the test''s one-tailed p-value", "UGHELLI''s hours as a share of all the hours in the comparison, which is its expected share of the events if the rates were equal", "The ratio of UGHELLI''s rate to the IOGP rate expressed per million hours, divided by the published IOGP figure of 0.81"]'::jsonb, 2, 'Given the total events and equal rates, UGHELLI''s share of the events is binomial with its share of the hours as the probability, and that share is 0.000611. The observed share of events is a different figure. The p-value is 0.000301, central and two-sided. A ratio of rates is 4.796684, nowhere near 0.000611.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 14, 'A risk assessment document for the same field reports a predicted FAR next to the site''s recorded fatalities. What does the course''s vocabulary require of the recorded one?', '["Call it the observed FAR, since here FAR is a rate counted after the fact and a predicted FAR is a different quantity", "Call it the FAR without qualification, since a FAR has one IOGP definition wherever it appears in a report or a document", "Call it the fatality severity rate, since the course reserves FAR for predicted rates drawn from a quantitative risk assessment", "Put both on the million-hour base, since an observed FAR and a predicted FAR only differ in the base they use"]'::jsonb, 0, 'The course''s vocabulary rule: here FAR is an observed rate, and the planned QRA course will teach a predicted one; write observed FAR wherever the two could be confused. The fixed IOGP definition is of the rate''s base and count, and it does not make an observed and a predicted figure the same thing. A severity rate is days lost per base hours. FAR''s base is fixed at 100,000,000 hours.'),
  ('safetystats', 'advanced', 'module', 'm04-benchmarking', 15, 'IOGP''s rule is a five-year rolling average. Run through `rollingRate` over 2020 to 2024 with a window of 5, what does the engine return?', '["5 windows, one per year, each carrying that year''s own FAR, from 0.550271 to 0.769438", "1 window, with a rate of 0.833228, since a rolling rate averages the rates inside its window", "No window, since a rolling window needs one more period than its length before it can start", "1 window, with a rate of 0.826095, the same figure as the pooled rate over the five years"]'::jsonb, 3, 'One complete window of 5 years exists in a 5-year series, and a rolling rate is sum then divide inside the window, so it returns 0.826095, the pooled figure for the same five years. The mean of the rates, 0.833228, is shown for comparison only. A window of 5 needs 5 periods, no more.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 1, 'AMUKPE''s company recorded 4 recordables in 846200 hours. A report divides those 4 events by the company and contractor hours together, 2238950, and prints 0.357310 per 200,000 hours. What is wrong with that figure?', '["Nothing, since adding the contractor hours gives a larger denominator and so a more precise company rate", "Its count and its hours describe different workforces: the contractor hours are in and the contractor events are out", "Its base is wrong, since a rate that includes contractor hours has to be quoted per 1,000,000 hours", "Its count is too high, since the company''s 4 events should be shared out across both workforces'' hours"]'::jsonb, 1, 'Events and hours must come from the same workforce, both in or both out. The row divides the company''s events by hours worked mostly by people who could never add to that count, and the rate falls from 0.945403 to 0.357310 with no change on site. More hours only help when their events come with them. The base is the caller''s choice for any workforce. The 4 events are the company''s and belong over the company''s hours.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 2, 'Which two AMUKPE rates are fair, and what does each answer?', '["0.357310 for the company and 1.161259 for the site, since both of them divide by the site''s full hours", "0.945403 for the company and 0.357310 for the site, since the site rate is the one that uses the site''s hours", "1.161259 alone, since a rate that leaves the contractors out is never a fair rate for a site to report", "0.945403 for how the company''s own people fared and 1.161259 for everyone exposed on the site"]'::jsonb, 3, 'The company row keeps contractors out of both halves; the site row keeps them in both. Both are honest and they answer different questions, which a report must name. 0.357310 is the mismatched row, the company''s events over everyone''s hours, and describes no workforce. A company-only rate is a fair statement about the company''s own employees, and many operators report both.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 3, 'AMUKPE''s company rate is 0.945403 and its site rate is 1.161259, both per 200,000 hours. What does that tell you about the contractors'' own rate, and why?', '["It is higher than 1.161259, because the pooled site rate is an hours-weighted average and must sit between the two groups", "It is lower than 0.945403, because the contractors worked more hours and more hours always give a lower rate", "It is 1.161259 exactly, because the site rate is the rate of the larger workforce once the two are pooled", "It cannot be said without the mean of the two groups'' rates, which is the figure the site rate is built on"]'::jsonb, 0, 'A pooled rate is a weighted average of the group rates with hours as the weights, so it lies between them. The site rate is above the company''s, so the contractors'' rate must be above the site''s. More hours make a rate more precise and do not push it down. The site rate is sum then divide over both groups, and the mean of the group rates is a different number that plays no part in it.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 4, 'The second AMUKPE row, 0.357310, sits below the company rate, the site rate and the contractors'' own rate. Why does that position give it away?', '["It does not give anything away, since a rate that divides by the site''s hours is always the lowest of the site''s recorded rates", "It shows the company improved over the year, since adding the contractor hours reveals the company''s own true underlying rate", "A rate that pools real groups must lie between their rates, so a combined figure outside that range has broken the counting", "It shows the contractors were safer than the company, since their hours lowered the rate when they were added in"]'::jsonb, 2, 'The pooled rate is an hours-weighted average of the group rates, so it can never fall outside them. When a combined figure lands outside the range of its parts, something in the counting has gone wrong, and here the contractor events are missing from the numerator. Nothing about the company''s own performance changed. The contractors'' rate is the highest of the three, which is the opposite of safer.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 5, 'Two of AMUKPE''s 13 site recordables are reclassified to first aid. The recordable rate falls from 1.161259 to 0.982603. What happens to the severity rate on the same hours, and what does that show?', '["It falls in proportion to the recordable rate, because days lost are counted only on recordable cases", "It stays at 5.181000, because the 58 days lost do not move, so the fall is a change in counting", "It rises, because the same 58 days lost now sit on fewer recordables over the same hours", "It cannot be computed after a reclassification, because its base must be restated for the new count"]'::jsonb, 1, 'The severity rate is days lost times the base over the hours, and the days belong to the injured people whatever the case is called: 5.181000 before and after. A recordable rate that falls while the severity rate holds still says the injuries are the same and the labels are different. The severity rate does not divide by the number of cases, so moving cases between boxes leaves it alone.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 6, 'Which pair of figures, reported side by side, protects a monitoring note against a fall in the rate that is only a change of labels?', '["A recordable rate and a severity rate on the same hours and base, since only one of them responds to a relabelling", "A recordable rate on 200,000 hours and the same rate on 1,000,000 hours, since the second one exposes a relabelling in the first", "A recordable rate and its 95 percent interval, since the interval widens whenever cases are moved across to first aid", "A company rate and a site rate, since a relabelling only ever takes place in the contractor part of a site''s register"]'::jsonb, 0, 'Two figures that respond differently to a change of labels expose it: when the recordable rate moves and the severity rate does not, the note has to explain why. The same rate on two bases differs by the factor of five and nothing else. An interval reflects the count it is given, relabelled or not. Reclassification can happen anywhere in a register.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 7, 'Which pattern of reclassification should make a reader suspicious of a falling recordable rate?', '["Any reclassification at all, since a case first logged as a medical treatment case can never be corrected later", "Reviews that move cases in both directions, since two-way movement shows the register is unstable", "Reviews that only ever move cases down, cluster near the year end, or happen at sites with a target to hit", "Reviews that happen within the month of the injury, since a quick review is always a biased one"]'::jsonb, 2, 'Reclassification can be right: a case first logged as medical treatment may on review have needed only first aid, and correcting the record is part of keeping a good register. The trap is the pattern. The test is whether the same review, applied to cases on the other side of the line, would ever move one up; movement in both directions is what an honest review looks like. The timing of a prompt review is no evidence of bias.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 8, 'Why can the engine not catch AMUKPE''s reclassification?', '["It can, since `incidenceRate` refuses any count that falls by more than 10 percent between two periods", "It can, since the engine compares a recordable count against the days lost and refuses a mismatch", "It can, since the basis block reports a changed count so a reader sees that the count was altered", "It checks that a count is a whole number, zero or more, and that the hours are positive; it cannot check a classification"]'::jsonb, 3, 'The count arrives classified. The refusals catch a fractional count, a negative count and zero hours, and nothing in the engine refuses a count that was classified wrongly. It keeps no history between calls, never sets days lost against a count, and its basis block states the base and the formula for whatever count it was handed. The analyst is the only check, so the note reports every reclassification in the period.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 9, 'EGBEMA''s worst month, month 8, reads 7.599326. The next month reads 2.067504. A programme launched in response to month 8 claims the fall. What does the chart say?', '["The programme worked, since the rate fell to about a quarter of month 8''s figure in a single month once it was launched", "The fall is what the chart predicts with no programme at all: month 9 sits inside its limits like the ordinary months", "The programme worked, since month 9 is below the centre line of 2.893273 and month 8 was far above it", "The programme failed, since month 9 recorded 4 events, and a working programme would have brought zero"]'::jsonb, 1, 'A month picked because it was the worst is likely to be followed by a better one even if nothing changed. Month 9''s 4 events sit below the 5.597615 expected at the centre, as ordinary months do, and the chart gives no reason to think the process changed. Crediting the programme with that fall is rate chasing. Four events is an ordinary month on this chart, and no programme is judged against a zero.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 10, 'Month 8 signals at 3 sigma, so on the chart''s own logic chance alone is an unlikely explanation for it. Does that rescue the programme''s claim to month 9''s fall?', '["Yes: once chance is ruled out for month 8, the fall from month 8 to month 9 can only be the effect of the programme itself", "Yes: a signalling month cannot be followed by a return to the centre unless something acted on the process", "No: a signal at 3 sigma shows the chart is wrong about month 8, so both months should be dropped from it", "No: whether month 8 was bad luck or a one-off with a cause, month 9 returns to the ordinary process whatever was launched"]'::jsonb, 3, 'Either way the programme gets no credit. If month 8 was partly bad luck, regression toward the centre explains the fall; if a one-off cause is found, the one-off does not repeat and the next month returns to the ordinary process. Ruling out chance for month 8 points to a cause in month 8, and a signal is investigated; it does not invalidate the chart.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 11, 'How should a monitoring note guard against rate chasing on a programme launched after a bad month?', '["Fix the start and the months on each side before looking, compare whole periods, and say that the programme started at a peak", "Compare the worst month with the month after it, since that pair of months shows the programme''s effect most directly and quickly", "Compare the programme''s first month with the site''s best month on record, since the best month sets the target it then has to beat", "Leave the launch month out of the note, since a reader who knows it came at a peak will doubt the programme"]'::jsonb, 0, 'A single month set against its neighbour proves nothing, and two months chosen after the fact are chosen for their result. The comparison that counts uses periods fixed before the data were read, and on EGBEMA it finds nothing: 1.028627 with every month in. Every reader deserves to know the baseline was the worst month, so the note says so.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 12, 'KWALE''s three sites give a mean of site rates of 1.754760 against a pooled 0.968312. Which site does most to open that gap?', '["The flow station, whose 1904760 hours make it by far the heaviest of the sites in the mean of the three site rates", "The compression station, whose rate of 1.171189 sits closest to the mean of the three site rates", "The jetty, with 61480 hours, a share of 0.024805 of the pooled hours, yet a third of the weight in the mean", "None of them, since the mean of rates and the pooled rate weight each of the three sites the same"]'::jsonb, 2, 'The mean of rates gives each site one third, derived 0.333333, whatever its exposure. The jetty''s 3.253090 on 61480 hours carries almost no weight in the pooled rate and a full third in the mean, which is what lifts the mean. The mean is unweighted, so the flow station''s hours count for nothing there. Sitting near the mean does not open a gap. Pooling weights by hours.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 13, 'An industry body averages its members'' reported rates to publish one figure. How does the Expert tier describe that?', '["The correct method for an industry body, since each member is one company and deserves one equal vote in the published figure", "An acceptable shortcut, since averaging rates and pooling them give the same figure once enough member companies report their rates", "The method IOGP uses for its own five-year FAR, which is why its published figure is quoted as 0.833228", "The KWALE mistake one level up: IOGP itself pools, and its five yearly FARs average to 0.833228 against a pooled 0.826095"]'::jsonb, 3, 'A group or an industry body that averages rates makes KWALE''s mistake at a larger scale: small units with high rates get a full vote. IOGP computes its five-year rolling average as the sum of fatalities over the sum of hours, 0.826095; the mean of 0.833228 is what it would print if it averaged its yearly rates, and it does not. The two methods differ by construction whatever the number of members.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 14, 'AKASO''s first rolling window reads 1.208038 by sum then divide and 2.026485 as the mean of its monthly rates. Why is the mean so much higher?', '["The shutdown in month 5 enters the mean as a rate of zero, which lowers the pooled figure far more than the mean", "The short month 11, 1 recordable in 18240 hours, has its own rate of 10.964912 and enters the mean with a full month''s weight", "The window includes 13 recordables, and the mean divides them by the 11 months with hours in place of the hours", "The rolling rate leaves out the short month as incomplete, while the mean of the monthly rates keeps it in"]'::jsonb, 1, 'Every window contains the short month, and its rate of 10.964912 counts as one month among eleven in the mean, while in the pooled rate its 18240 hours carry almost no weight. A month with no hours has no rate and is left out of the mean; it adds nothing to the pooled figure. The mean averages rates, and the rolling rate includes every month in its window.'),
  ('safetystats', 'advanced', 'module', 'm05-the-traps', 15, 'Why does the mean of rates keep spreading through group reporting, according to the Expert tier?', '["It is easy: each unit reports one number and head office averages them without ever collecting any hours", "It is the method the OSHA base prescribes for combining sites, so a group quoting per 200,000 must use it", "It is more conservative, since the mean of rates always sits above the pooled rate and so errs toward safety", "It is what the engine returns as its rate, so a group copying the engine''s output repeats the mean of rates"]'::jsonb, 0, 'Pooling needs counts and hours from every unit, defined the same way, which is more work, and that is exactly why the error spreads. The base says nothing about how to combine sites. The mean sat above the pooled figure on every stream in the course, but it can sit anywhere, and a direction that happens to hold is not a method. The engine returns the pooled rate as its rate and shows the mean beside it, labelled.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 1, 'The Expert tier reads a year on one chart in a fixed order. Which order is it?', '["The signals first, since they are what the chart is for, then the limits that produced them, and the centre last", "The before-and-after comparison first, since it answers the question the programme asked, and then the chart itself", "The highest reading first, since the month that looks worst is the one a reader will ask about before any other", "The base and the grain, then the centre, then the limits, then the signals, and only then what was done about them"]'::jsonb, 3, 'The order exists so that nothing gets skipped because something else looked more interesting: base and grain, the pooled centre, the limits and their floor, the signals, then causes, revision and any intervention. Starting from the comparison hides whether a month was set aside to produce it. Starting from the highest reading would have started EGBEMA at month 3, which does not signal.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 2, 'The Expert tier''s monitoring note has five parts. Which list gives them in the order the tier grades?', '["Every rate with its base and interval; the before-and-after claim; the signals; any revision; and the chart and its centre last as a summary", "The chart and its centre; the signals and what was found; any revision and its months; any before-and-after claim and its months; every rate with its base and interval", "The before-and-after claim and its p-value; the chart and its centre; the signals and what was found; the revision; and the rates with their intervals", "The chart and its centre; any revision and its months; the signals and what was found; every rate with its interval; the before-and-after claim"]'::jsonb, 1, 'The course lists the parts: the chart and its centre, the months that signal and what was found, whether the limits were revised and on which months, any before-and-after claim with the months it used, and every rate with its base and its interval. A reader who meets the ratio first cannot tell whether a month was set aside to produce it, and a revision only makes sense after the signal and its finding.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 3, 'For AMUKPE''s site rate, which of these decisions rests entirely with the caller, with nothing in the engine able to check it?', '["Whether the hours are finite and above zero, since a rate over no exposure is left for the caller to catch", "Whether the count is a whole number, since the engine rates a fractional number of recordables as readily as a count", "Whose hours are in the denominator, since the engine cannot tell whether they match the workforce behind the count", "Whether a base has been named, since the engine applies the 200,000 hour base by default when a caller leaves it out"]'::jsonb, 2, 'The engine checks the shape of an input: a zero-hours call is refused, a fractional count is refused, and a missing base is refused by name because there is no default. Whether an injury was recordable, whether a release was Tier 1, and whose hours sit under whose events are the caller''s decisions. A mismatched denominator passes every check the engine makes and returns a clean number.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 4, 'A caller passes a process safety event count to `pseRate` with a tier of 3. What does the engine return?', '["A refusal naming `tier`, in the engine''s own words: tier must be 1 or 2: classify the events against API RP 754 before rating them", "A Tier 2 rate, since the engine treats any tier above 2 as the lowest tier it rates and says so in the basis block", "A rate with a warning attached, since the engine rates any whole-number tier and flags a tier it does not recognise", "A refusal naming `pseCount`, since the engine classifies the events itself and finds that none of them fit tier 3"]'::jsonb, 0, 'The tier is an input, and the engine accepts 1 or 2 only; a tier of 3 or a missing tier is refused with that message. It never maps one tier onto another and returns no warnings: a call either returns a result with its basis or an error with its field. The engine does not classify events at all, because the threshold quantity tables it would need are licensed and absent.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 5, 'AMUKPE''s site rate is 1.161259 before two recordables are reclassified to first aid and 0.982603 after. How does the engine''s output mark the difference?', '["It does not: both results carry the same six decimals and the same clean basis block, and only the note can say what changed", "The second result carries a reclassified flag in its basis block, since the engine compares each count with its last call", "The second result is refused, since a recordable count that falls while days lost stay put fails the engine''s consistency check", "The second result is returned with a wider interval, since the engine adds uncertainty for any count it cannot fully verify"]'::jsonb, 0, 'The engine can make a correctly classified count into a correctly computed rate, and it will return a wrong count''s rate the same way. It keeps no memory between calls, sets no count against days lost, and `incidenceRate` returns no interval at all. That is why the note reports every reclassification in the period, how many cases moved and in which direction.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 6, 'EGBEMA''s year in one sentence has four clauses. Which clause does the chart NOT support?', '["One month, month 8, signalled high against its own upper limit on the chart as drawn", "The other eleven months are consistent with a stable process at the exposure recorded", "The intervention lowered the rate, as the set-aside row''s ratio of 0.677882 shows", "The chart could not have detected a fall, since every lower limit was floored at zero"]'::jsonb, 2, 'The summary the tier writes is: one month signalled high, the rest are consistent with a stable process at the exposure recorded, the chart could not have detected a fall, and the intervention cannot be shown to have changed the rate. The 0.677882 row is admissible only on a found cause for month 8, and even then its interval, 0.357764 to 1.257771, includes 1. The other three clauses each rest on a figure the chart printed.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 7, 'The investigation into EGBEMA''s month 8 closes without finding a cause. What does the monitoring note then report?', '["Month 8 comes out anyway, since a month that signals and resists explanation is the clearest outlier the chart has, which gives a centre of 2.389523", "Month 8 is replaced by the centre''s expected count of 6.091641 events, so that the chart keeps twelve months while the outlier''s effect is removed", "The comparison with month 8 set aside, 0.677882 with a p-value of 0.241552, since a month with no known cause cannot be trusted as data", "Month 8 stays in: the drawn chart with its 2.893273 centre stands, and the all-months comparison, 1.028627 with a p-value of 1.000000, is the one"]'::jsonb, 3, 'Where nothing is found the note says so and the month stays, as part of the process. Setting a month aside because it is high is removing the data that disagree, and replacing it with an expected count is the same move in disguise. The set-aside row is admissible only on a found cause, so without one the all-months row is the comparison, and it shows no change.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 8, 'Which rate is written in the house form the course uses for a rate with its uncertainty?', '["3.500000 (7 cases; interval 1.407182 to 7.211338), since the base is understood once a report states it", "3.500000 per 200,000 hours (7 cases in 400000 hours; 95 percent exact interval 1.407182 to 7.211338)", "3.500000 per 200,000 hours, with 7.211338 quoted alone as the highest value the rate could take at 95 percent", "3.500000 per 200,000 hours plus or minus half the width of its 95 percent exact interval"]'::jsonb, 1, 'The house form carries the rate, the base, the count and hours it came from, and the interval with its confidence. A base left implicit is how a factor of five creeps in. No P label is used for a confidence interval anywhere in this course, because the interval is on an estimated rate. The exact interval is not symmetric about the rate, so a plus or minus figure misdescribes it, and an upper limit quoted alone drops the lower one and the count.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 9, 'A learner checks the engine''s p-value for a comparison in another tool and gets a smaller number. On UTOROGU the engine reads 0.051759. What is the most likely explanation?', '["The other tool is correct and the engine has a rounding defect, since two tools computing one exact test must agree to six places", "The other tool computed the p-value on the 1,000,000 hour base, and a larger base always shrinks the p-value of a comparison", "The other tool assumed equal hours in the two groups, which is the default of every exact test and shrinks the p-value on UTOROGU", "The other tool uses the minlike convention, which gives 0.025879 on UTOROGU; the engine''s central p-value is twice the smaller tail"]'::jsonb, 3, 'The engine''s choice is declared: a central p-value, twice the smaller tail capped at 1, the test the Clopper-Pearson interval inverts. R''s poisson.test and scipy''s binomtest use the minlike convention and read 0.025879 on UTOROGU. On UTOROGU the minlike figure happens to equal the smaller tail, because no count on the other side is as unlikely as the one observed; on other counts it need not be, and no fixed factor converts one convention into the other. No base enters a comparison, since it cancels in a ratio, and the engine conditions on the actual hours.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 10, 'Rehearsing the Expert capstone''s six kinds of figure on EGBEMA, which two depend on a decision about which months to keep?', '["The centre, 2.893273, and month 3''s upper limit, 10.211920, since both change when any month is kept", "Month 1''s lower limit and its flag, since the floor is applied only to the months the analyst chose to keep", "The revised centre, 2.389523, and the before-and-after p-value with month 8 set aside, 0.241552", "The all-months p-value, 1.000000, and the centre, since both need the analyst to choose a set of months"]'::jsonb, 2, 'Four of the six figures are read off the chart and the comparison as given: the centre, an upper limit, a lower limit with its lclFloored flag, and the all-months p-value. The revised centre and the p-value with a month set aside exist only because someone decided to set a month aside, which is why each needs a stated basis. The floor follows from the exposure, and the all-months comparison uses every month by definition.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 11, 'Working a chart and a before-and-after comparison end to end, which of these is one of the mistakes the Expert tier says recur?', '["Counting a point that sits exactly on its limit as a signal, when the engine''s rule is a point strictly outside", "Reading each lower limit off the engine together with its `lclFloored` flag, since a limit may be floored or positive", "Naming a flagged month in the reader''s numbering from 1, while the engine''s `outOfControl` list is zero-based", "Running the comparison twice, once with every month in and once with the named month set aside on its stated basis"]'::jsonb, 0, 'Four mistakes recur: the mean of the monthly rates taken as the centre, a point on its limit counted as a signal, a month set aside because it is high, and a p-value typed from a tool that uses the minlike convention. The other three options are the method itself: a lower limit read with its flag, a note that numbers months from 1 against a zero-based list, and both comparisons run with the basis for the set-aside month stated.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 12, 'Which three questions does the Expert tier say to ask of every rate you are handed, since the engine never asks them?', '["Whether the count is a whole number; whether the hours are above zero; whether the base has been named by the caller", "Whether the rate has six decimals; whether it carries a basis block; whether the basis block names the standard it followed", "Whether the rate is below the IOGP figure; whether it fell from last year; whether the site met its target for the year", "Who classified the count and against which definition; whether the classification changed in the period; whether a review would ever move a case up"]'::jsonb, 3, 'Those are the classification questions, and the engine cannot see any of them. A whole count, positive hours and a named base are exactly what the engine already checks, and a clean basis block comes with a wrongly classified count as readily as a right one. A benchmark, a trend and a target are comparisons, and they inherit whatever the classification got wrong.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 13, 'UGHELLI recorded 1 Tier 1 process safety event in 2318640 hours. What can the course say about it?', '["Its Tier 1 PSE rate is 0.086257 per 200,000 hours, and the engine confirmed it as Tier 1 against API RP 754", "Given the tier, its Tier 1 PSE rate is 0.086257 per 200,000 hours; the tier itself was decided outside the engine", "Its Tier 1 PSE rate is 0.431287 per 1,000,000 hours, since that is the one base the engine will accept for a PSE rate", "Its Tier 1 PSE rate cannot be computed, since the engine refuses a single event as too few to rate at all"]'::jsonb, 1, 'A learner who is given a tier can rate it; a learner who is given a release has to classify it outside this engine, because the threshold quantity tables are licensed and not in it. The PSE rate takes the 200,000 or the 1,000,000 base, 0.086257 on the first and 0.431287 on the second, and the FAR base is refused. A count of 1 is a whole number, zero or more, and is rated normally.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 14, 'Why does the monitoring note put the chart before any before-and-after claim?', '["So that the reader knows which months were unusual, and whether any was set aside, before a claim about them is made", "So that the note is shorter, since a chart summarises the whole year and a comparison only repeats what it already shows", "So that the p-value can be computed from the chart''s centre line, which the comparison then needs as one of its own inputs", "So that the reader sees the favourable comparison last, which leaves the strongest possible impression of the programme"]'::jsonb, 0, 'A reader who meets the before-and-after ratio first has no way to know whether a month was set aside to produce it. The chart and the comparison answer different questions and neither repeats the other. The comparison takes counts and hours for two periods and never uses the centre line. Arranging a note for impression is the opposite of what its order is for.'),
  ('safetystats', 'advanced', 'module', 'm06-judgement-end-to-end', 15, 'EGBEMA''s note must describe the chart''s low side. What does it say, and why?', '["That no month fell below its lower limit, which shows that reporting on the site stayed complete and honest through the whole year", "Nothing, since a floored lower limit is an engine detail that the reader of a monitoring note has no real need to be told about", "That every lower limit was floored at zero, so the chart could only ever find high months and a fall would have gone unseen", "That the low side was tested at 2 sigma in place of 3, since the 3 sigma lower limits could not be drawn at all"]'::jsonb, 2, 'The chart part of the note names the base, the grain and the centre and says that every lower limit was floored. A u cannot be strictly below zero, so no low signal was possible, and a quiet low side is no evidence about reporting. The floor matters to the reader because it limits what the chart can claim. The engine draws only 3 sigma limits.'),
  ('safetystats', 'advanced', 'final', null, 1, 'EGBEMA''s month 12 recorded 4 events in 405240 hours. On the 200,000 hour base, what u does the chart plot for it?', '["2.026200, the month''s exposure units, since a u-chart plots each month''s share of the base", "4, the month''s count, since a u-chart plots the events recorded in each month directly", "1.974139 per 200,000 hours, the 4 events over the month''s 2.026200 exposure units", "2.893273, the pooled centre line, since a month that does not signal is plotted on the centre"]'::jsonb, 2, 'Units are hours over the base, 405240 over 200,000, and u is the count over the units, the month''s rate on the base: 1.974139. The units are the denominator of u. Plotting raw counts would ignore the exposure the chart is built to carry. Every month is plotted at its own u, and the centre is the line it is judged against.'),
  ('safetystats', 'advanced', 'final', null, 2, 'EGBEMA''s 63 events sit on 21.774650 exposure units. What does that second figure measure?', '["The sum of the twelve monthly u values, whose average is the chart''s centre line of 2.893273 per 200,000 hours", "The whole year''s hours divided by the 200,000 hour base, which is the denominator of the centre line", "The headcount on site averaged across the year and divided by 100, the OSHA base''s 100 full-time workers", "The number of base periods in the year that recorded at least one event, since a unit is one eventful month"]'::jsonb, 1, 'Each month''s units are its hours over the base, so the sum is the year''s hours over the base, and 63 over it gives the pooled centre, 2.893273. The mean of the monthly u is a different figure, 3.202958. The engine takes hours and has no headcount input. A unit is one base''s worth of hours, whatever happened in it.'),
  ('safetystats', 'advanced', 'final', null, 3, 'EGBEMA''s month 4 has an upper limit of 7.084918, the second widest on the chart after month 3. Why?', '["Its u of 3.373705 is the second highest among the quiet months, and the band widens with the reading", "Its 5 events are the second highest count in the first half, and the band is set by the month''s count", "Its 296410 hours give 1.482050 units, the second fewest on the chart, and fewer units mean a wider band", "Its limit is drawn from the average month''s exposure, which the engine uses for every month before month 7"]'::jsonb, 2, 'The limit is ubar + 3 sqrt(ubar / n_i), so after month 3''s 0.486150 units, month 4''s 1.482050 give the next widest band. A month''s own u and count play no part in its limits. Limits from the average exposure are an approximation that would give every month one band, and it fails worst on a month as thin as month 3; the engine uses each month''s own units throughout.'),
  ('safetystats', 'advanced', 'final', null, 4, 'An analyst draws EGBEMA''s centre at 3.202958, the mean of the monthly u, and builds the limits around it. What goes wrong?', '["Nothing, since the mean of the monthly u and the pooled centre agree on any chart whose months carry similar counts of recordable events", "Only the lower limits move, since the upper limits depend on each month''s units alone and ignore where the centre sits", "The chart flags more months, since a higher centre narrows every band and so pushes the high months over their moving upper lines", "Every limit is measured from a centre that gives the thin month 3 a full twelfth of the weight, so the whole band sits too high"]'::jsonb, 3, 'The engine''s centre is sum then divide, 2.893273, weighting each month by its units. The mean lifts the centre because month 3''s 8.227913 rests on 0.486150 units yet counts one twelfth, and every limit, upper and lower, is ubar plus or minus 3 sqrt(ubar / n_i), so both move up with it. A higher centre widens each band, since ubar sits under the square root, and so flags fewer months. The two figures differ on EGBEMA whatever the counts look like.'),
  ('safetystats', 'advanced', 'final', null, 5, 'An analyst prints EGBEMA''s raw lower limits, which are negative, in place of the engine''s 0.000000. What is wrong with that?', '["Nothing, since a negative lower limit lets a month with zero events signal low, which a floor at zero would hide", "The negative limit would flag every month below, since each u is further from the centre than a negative limit allows", "A negative limit is a line no month could cross, since no count falls below zero; the engine floors it at zero and flags it", "The negative limit changes the upper limits too, since the engine sets the band''s width from the lower limit it prints"]'::jsonb, 2, 'No rate can be negative, so a limit below zero suggests a precision that is not there. The engine sets it to zero and says so with `lclFloored` true, which is the declared choice. Either way no month can signal low: a u of zero is not strictly below zero, and still less below a negative line. The upper limit is ubar plus the same square root term and does not depend on how the lower one is printed.'),
  ('safetystats', 'advanced', 'final', null, 6, '`pooledRate` accepts a mothballed site with 0 hours and 0 events, returning a null period rate. `uChart` refuses a period with no hours. Why the difference?', '["A pooled rate only sums counts and hours, so an empty period adds nothing; a chart has to place every point, and a point with no hours has nowhere to go", "The pooled rate is computed on the million-hour base, where a period with no hours rounds to a very small exposure and can safely be carried", "The u-chart refuses the period only when it also carries events, and a mothballed site with no events would be charted at a u of zero", "The two functions were written to different standards, and the engine''s u-chart follows a stricter data rule that the pooled rate lacks"]'::jsonb, 0, 'The u-chart''s refusal names the zero-hour field and tells the caller to drop that period first. A point''s u and limits both divide by its units, and zero hours give zero units. The chart refuses a zero-hour period whether or not it carries events, and the base plays no part. The pooled rate sums, so an empty period leaves the pooled figure at 0.968312.'),
  ('safetystats', 'advanced', 'final', null, 7, 'AKASO''s 15 months include month 5, a shutdown with no hours. What should be passed to `uChart`, and what happens if all 15 months go in as they stand?', '["All 15 months; the engine charts month 5 at a u of 0.000000 and floors its lower limit, as it does for any quiet month", "The 14 months with hours; passed whole, the engine refuses and names `exposureHours[4]`, the zero-based index of month 5", "The 14 months with hours; passed whole, the engine refuses and names `exposureHours[5]`, since its fields count from month 1", "The 13 months other than months 5 and 11, since the short month of 18240 hours is refused as well for being too thin"]'::jsonb, 1, 'A period with no hours must be dropped before charting, and the refusal names the first zero-hour index, which is zero-based, so month 5 is `exposureHours[4]`. The engine never charts a zero-hour period. Month 11 is thin, 18240 hours, and thin is legitimate data: the chart simply gives it a wide band.'),
  ('safetystats', 'advanced', 'final', null, 8, 'Which EGBEMA month would signal at 2 sigma that does not signal at the engine''s 3 sigma?', '["Month 8, whose u of 7.599326 clears its derived 2 sigma limit of 5.237783, a band it does not clear at 3 sigma", "Month 4, whose u of 3.373705 clears its derived 2 sigma limit of 5.687703 on its 1.482050 exposure units", "Month 3, whose u of 8.227913 clears its derived 2 sigma limit of 7.772371 and sits inside its 3 sigma limit", "No month, since the 2 sigma and 3 sigma bands flag the same months on any chart with a pooled centre line"]'::jsonb, 2, 'Month 8 signals at both bands, 7.599326 against 6.410039 at 3 sigma and 5.237783 at 2 sigma, so it adds nothing new. Month 3 is the one extra flag: 8.227913 against 7.772371 at 2 sigma and against 10.211920 at 3 sigma. Month 4''s 3.373705 is below 5.687703. A narrower band flags more months, which is its cost.'),
  ('safetystats', 'advanced', 'final', null, 9, 'In the golden case uchart-points-on-the-limits, ubar is 1 and each point carries 9 units, so the limits are exactly 0 and 2. Point 1 recorded 18 events and point 2 recorded 0. Had point 1 recorded 19, what would the engine return for the two points?', '["above for point 1 only, since one point''s count leaves the other point''s limits and its signal exactly as they were", "above for point 1 and below for point 2: the extra event lifts the pooled centre and the lower limit off zero", "null for both, since a single event more than the limit is within the rounding the engine allows", "above for point 1 and null for point 2, since a u of zero sits on a lower limit that stays at zero"]'::jsonb, 1, 'The centre is pooled, so 19 events on 18 units lift it above 1, and both points share that centre and their 9 units. The upper limit rises too, but u rises faster, and 19 over 9 lies strictly above it: point 1 returns above. The lower limit, the centre minus 3 times the square root of the centre over 9, is exactly 0 at a centre of 1 and rises above 0 as the centre rises, so point 2''s u of 0.000000 now lies strictly below it and returns below. Changing one count redraws the whole chart. The engine applies no rounding allowance.'),
  ('safetystats', 'advanced', 'final', null, 10, 'On the golden low-point chart, point 1 recorded 48 events in 5000000 hours: a u of 1.920000 against limits of 0.936592 and 2.512443. What does the engine return for it?', '["below, since its u of 1.920000 is under the 2.000000 that most of the other points on the chart read", "null: its u lies between its limits, and only point 4, at 0 events, falls outside and signals below", "above, since its 48 events on 5000000 hours sit at the top of the chart''s range of monthly counts", "below, since any point under the centre line on a chart with positive lower limits is a low signal"]'::jsonb, 1, 'A signal needs a u strictly outside the point''s own limits: 1.920000 lies between 0.936592 and 2.512443. Sitting under the other points'' readings or under the centre is ordinary variation. Of the seven points, only point 4, 0 events in 4800000 hours against a lower limit of 0.920345, signals, and the golden reads it as a case for checking the reporting.'),
  ('safetystats', 'advanced', 'final', null, 11, 'In the golden small-exposure case, points 1 and 2 carry 2000 hours each and point 3 carries 400000. Why is point 3''s upper limit, 4.965310, so much tighter than their 44.196051?', '["Point 3 has two hundred times their hours, so its distance from the centre is smaller by the square root of two hundred", "Point 3 recorded only 1 event, and the engine tightens a point''s upper limit when its count is small", "Point 3''s hours exceed the base, and the engine draws a point above the base on a tighter scale than the rest", "Point 3 has two hundred times their hours, so its distance from the centre is two hundred times smaller"]'::jsonb, 0, 'The golden''s note: two thin periods: limits scale with 1/sqrt(n_i). The distance from the centre to the limit is 3 sqrt(ubar / n), so two hundred times the units shrinks it by the square root of two hundred. A count plays no part in its limit, and the engine treats every point on one scale whatever its hours.'),
  ('safetystats', 'advanced', 'final', null, 12, 'The engine''s method line fixes the limits at 3 sigma. What does that convention accept, in exchange for flags that are usually worth investigating?', '["That a real change of any size will be missed until a year has closed", "That every flag on a stable process will turn out to be a real change", "That a modest real change may take a while to show on the chart", "That months with few hours are left off the chart until they fill up"]'::jsonb, 2, 'Three sigma is a trade: fewer flags on a stable process, each usually worth the investigation, at the price of detecting a modest change more slowly. A large change can still signal in the month it happens, as month 8 does. Flags on a stable process are mostly chance at any band. Thin months stay on the chart with wide limits.'),
  ('safetystats', 'advanced', 'final', null, 13, 'Month 3 on EGBEMA had 0.486150 units, an upper limit of 10.211920, and 4 events. What count would sit exactly on that printed limit?', '["About 10, since the upper limit of 10.211920 is itself a count of events and needs no conversion before it is read", "Exactly 4, since month 3''s u of 8.227913 already sits on its upper limit once the reading is rounded", "About 21, the limit divided by the units, since a rate per unit becomes a count by dividing by the units", "Just under 5, the limit times the units, so on the drawn chart month 3''s 4 events sit about one event inside it"]'::jsonb, 3, 'The count on the limit is the limit times the units, 10.211920 times 0.486150, which is just under 5, so 4 events sit about one event inside the line as drawn. The limit is a rate per 200,000 hours and becomes a count only when multiplied by the units, and being near a limit is never a signal under the strict rule. A what-if count typed into the panel is a new chart: the added events lift the pooled centre and month 3''s limit with it, so a what-if is judged on the redrawn chart.'),
  ('safetystats', 'advanced', 'final', null, 14, 'A reader notices that month 11''s u of 1.018563 is the lowest on EGBEMA and asks whether it signals low. What is the answer?', '["It does, since the lowest u on a chart falls below the lower limit once the centre is pooled", "It would, if month 8 were set aside first, since the revised centre lifts every lower limit above zero", "It does, since a month whose u is under half the centre line is flagged below by the engine", "It cannot: like every month on this chart its lower limit is floored at zero, and a u above zero is inside"]'::jsonb, 3, 'Every EGBEMA lower limit is 0.000000 with `lclFloored` true, so no month on this chart can signal low. Setting month 8 aside lowers the centre to 2.389523, which lowers every lower limit further. The engine has no half-the-centre rule; a signal is strictly outside the limits.'),
  ('safetystats', 'advanced', 'final', null, 15, 'EGBEMA''s month 9 recorded 4 events on 1.934700 units. At the centre line it would be expected to carry 5.597615. How does month 9 read?', '["As a low signal, since 4 events is well short of the 5.597615 that the centre line expects of it", "As proof of improvement, since it follows month 8''s 16 events with a count of only 4", "As an ordinary month a little below the centre, inside its limits, with no signal to explain", "As a data fault, since an expected count of 5.597615 cannot be met by any whole count of events"]'::jsonb, 2, 'Its u of 2.067504 sits inside limits of 0.000000 and 6.561947, and an ordinary month falls a little above or below its expected count. A low signal needs u strictly below the lower limit, which is floored at zero here. A month read after the worst month proves nothing by itself. An expected count is a mean, so it need not be a whole number.'),
  ('safetystats', 'advanced', 'final', null, 16, 'Month 8 is set aside on a found cause. Which totals give EGBEMA''s revised centre of 2.389523?', '["The 63 events over the remaining units, since the events of a set-aside month stay in the count", "The mean of the eleven remaining monthly u values, since a revised chart is centred on the kept months", "The remaining 47 events over all 21.774650 units, since the hours of a set-aside month stay in", "The remaining 47 events over the remaining units, 21.774650 less month 8''s 2.105450"]'::jsonb, 3, 'The centre is sum then divide, so setting month 8 aside removes its 16 events and its 2.105450 units together, leaving 47 events on the rest. Dropping a month''s events and keeping its hours, or the reverse, describes no period at all. The mean of the kept u values is the mean-of-rates mistake on the revised chart.'),
  ('safetystats', 'advanced', 'final', null, 17, 'The investigation finds that a backlog of cases from earlier months was entered in month 8''s register. Which family of cause is that, and what changes if it is confirmed?', '["A change in the work: the count stays in month 8, since a case belongs to the month in which it was entered", "A change in the hours: month 8''s hours rise to match the backlog, and its count stays where it is", "A change in the workforce: the backlog shows new starters in month 8, so the month stays as drawn", "A change in counting: month 8''s count falls and the earlier months carry the cases they really belong to"]'::jsonb, 3, 'The Expert tier lists a backlog of earlier cases entered in one month as a counting change: it moves the count without the usual link to the month''s work. Confirmed, the cases go back to the months they occurred in, which changes those months'' counts as well as month 8''s. The hours are unaffected. Nothing about the work or the workforce is implied by a backlog.'),
  ('safetystats', 'advanced', 'final', null, 18, 'On the all-months before-and-after comparison, twice the smaller tail is a derived 1.015454. Which p-value does the engine report?', '["1.015454, because the central p-value is twice the smaller tail with no cap applied", "1.000000, because the central p-value is twice the smaller tail, capped at 1", "About half of 1.015454, because the engine reports the smaller tail itself as its p-value", "0.241552, because the engine reports the comparison with the flagged month set aside"]'::jsonb, 1, 'The method line says central two-sided p-value (twice the smaller tail, capped at 1). A probability cannot exceed 1, so 1.015454 is reported as 1.000000. Halving the doubled tail gives one tail, which is a different test. 0.241552 is the other row, with month 8 set aside, which needs a found cause.'),
  ('safetystats', 'advanced', 'final', null, 19, 'With month 8 set aside, the engine returns a central p-value of 0.241552. The programme lead reports half of it, as a one-tailed test of improvement. What is wrong?', '["Nothing, since a programme that aims to lower the rate is entitled to a one-tailed test of that aim once the result is in", "The one tail was chosen after seeing the direction, and the engine''s p-value is central, twice the smaller tail", "Nothing, since halving the central p-value is how the minlike convention of R and of scipy reports the same test", "Only the rounding, since half of 0.241552 must be quoted to six decimals like every other p-value"]'::jsonb, 1, 'The engine reports the central p-value and says so in its method line; a one-tailed figure chosen once the ratio is seen to be below 1 tests a question nobody declared in advance. Minlike is a different rule, and no fixed factor converts it to the central value. And this row stands only if month 8 had a found cause unrelated to the intervention, so halving its p-value compounds one flattering choice with another.'),
  ('safetystats', 'advanced', 'final', null, 20, 'An analyst compares EGBEMA''s 35 events after the intervention with 28 before and calls it a rise of a quarter, as if the two periods had equal hours. What does the engine''s comparison say?', '["On the actual hours, 2389010 after and 1965920 before, the rate ratio is 1.028627, and the test conditions on each period''s share of the hours", "The same rise of a quarter, since the conditional test compares the two counts directly and the hours only set the base of the ratio", "A fall, since the after period has more hours, and the conditional test always divides the larger count by the larger number of hours", "Nothing at all, since the engine refuses to compare two periods whose hours differ by more than a tenth of the larger period''s hours"]'::jsonb, 0, 'Equal hours is a real wrong method: the after period worked more hours, so its extra events are partly extra exposure. Given 63 events and equal rates, the after period''s share of events is binomial with its share of the hours as the probability, and the ratio of rates is 1.028627 with an interval of 0.607952 to 1.755328. The engine has no hours-difference refusal; a group with no hours is what it refuses.'),
  ('safetystats', 'advanced', 'final', null, 21, 'Many points on a site''s chart are as thin as EGBEMA''s month 3. What remedy does the Expert tier offer, and at what cost?', '["Draw the limits at 2 sigma, so the thin months signal as readily as the full ones, at no cost in extra investigation work for anyone", "Drop the thin months from the chart, so that only full months are judged, at the cost of a shorter chart to read", "Chart by week, so each point is fresher and its limits react faster, at the cost of a longer table to maintain", "Chart by quarter, so each point carries more exposure and tighter limits; a change then shows only once a quarter has closed"]'::jsonb, 3, 'Pooling the hours into coarser points raises each point''s units, so the limits tighten and a real change can show; the price is waiting for the quarter to close, and the grain is chosen and stated before the chart is read. A narrower band adds flags that are mostly chance. Thin months are legitimate data. Weekly points would be thinner still.'),
  ('safetystats', 'advanced', 'final', null, 22, 'Which pair of IOGP figures reproduces the published 2023 observed FAR of 0.82?', '["32 fatalities in 4158877000 hours, which the engine rates at 0.769438", "27 fatalities in 3291382000 hours, which the engine rates at 0.820324 per 100,000,000 hours", "21 fatal incidents in 4158877000 hours, which the engine rates at 0.504944 per 100,000,000 hours", "3071 recordables in 3795000000 hours, which the engine rates at 0.809223 per 1,000,000 hours"]'::jsonb, 1, 'The 2023 golden row is 27 fatalities in 3291382000 hours: 0.820324, which IOGP prints as 0.82, with a relative difference of 0. The 32-fatality row is 2024''s FAR, the 21-incident row is 2024''s fatal incident rate, and 3071 recordables give the 2024 TRIR on the million-hour base.'),
  ('safetystats', 'advanced', 'final', null, 23, 'UGHELLI recorded 0 fatalities in 2318640 hours, an observed FAR of 0.000000. How does it compare with IOGP''s 2024 observed FAR of 0.769438?', '["It says little: a zero on a few million hours bounds the rate from above, and that bound is what an interval supplies", "It shows UGHELLI safer than the industry, since any rate of zero sits below a published rate above zero", "It shows UGHELLI''s true rate is zero, since an observed FAR of zero is exact on any number of hours", "It cannot be computed, since the engine refuses a FAR with no fatalities as a rate over no events"]'::jsonb, 0, 'A zero FAR on a few million hours says little. The IOGP figure rests on billions of hours; UGHELLI''s rests on 2318640, and a zero count only bounds the rate from above, as the Professional tier''s zero-count interval showed. The engine returns 0.000000 without complaint, since a count of zero is a whole number, zero or more.'),
  ('safetystats', 'advanced', 'final', null, 24, 'A company reports its LTIF, lost time cases per million hours, beside IOGP''s 2024 TRIR of 0.81 on the same base. What is wrong with the comparison?', '["Nothing, since both rates sit on the million-hour base and so the one base check that matters most has already been passed in full", "A lost time count leaves out the restricted work and medical treatment cases a TRIR includes, so the two measure different harm", "The bases differ, since an LTIF is quoted per 200,000 hours and the TRIR per 1,000,000 hours by IOGP''s own convention", "Only the rounding, since IOGP prints two decimals and the company''s LTIF is quoted to six in its report"]'::jsonb, 1, 'Same base is necessary and not sufficient: the definitions must match too. A lost time count leaves out restricted work and medical treatment cases, so it will sit under a TRIR however the site performs. The name printed beside a number is not something the engine checks; the case class is the caller''s count. The base in the prompt is already shared.'),
  ('safetystats', 'advanced', 'final', null, 25, 'UGHELLI''s ratio to the IOGP 2024 TRIR has a 95 percent interval of 2.191251 to 9.117590. Which row of the Professional tier''s IMO ladder does its width most resemble?', '["The 100-event row, where the upper limit was 1.494848 times the lower, since IOGP rests on 3071 events", "The 1-event row, where the upper limit was 220.068159 times the lower, since a ratio compounds two counts", "The 5-event row, where the upper limit was 7.187207 times the lower, since UGHELLI has 4 DART cases", "The 10-event row, where the upper limit was 3.835008 times the lower, since UGHELLI rests on 9 events"]'::jsonb, 3, 'The interval''s width is almost all UGHELLI''s, 9 events, so its upper over its lower limit is of the order the ladder shows near 10 events. IOGP''s 3071 events make its rate behave nearly like a constant, so they do not set the width. The IOGP side adds almost nothing, so the width is not compounded. The recordable ratio rests on the 9 recordables, and the DART count is a different class.'),
  ('safetystats', 'advanced', 'final', null, 26, 'Which two statements can UGHELLI''s comparison with the IOGP 2024 TRIR support, with the base and definition checks holding?', '["Its rate on the IOGP base, 3.881586, is well above the published 0.81, and the ratio''s lower limit, 2.191251, is above 1", "It ranks in the worst tenth of IOGP members, and its p-value of 0.000301 measures how far it sits from the typical member", "Its rate is 4.796684 times every member company''s rate, and the interval shows how much the member companies differ", "Its rate is below IOGP''s, since 0.776317 is under 0.809223, and the p-value of 0.000301 confirms the difference"]'::jsonb, 0, 'The two safe statements are the gap on a shared base and the fact that the gap exceeds UGHELLI''s own count uncertainty. A ranking needs a distribution of company rates, which the pooled figure does not carry. The ratio is to the pooled membership, and its interval is UGHELLI''s uncertainty, which says nothing about how members differ. 0.776317 is on the 200,000 hour base and cannot be set beside a million-hour figure.'),
  ('safetystats', 'advanced', 'final', null, 27, 'Which is the one rate in the engine with a fixed base, and why is it fixed?', '["The TRIR, on 200,000 hours, because OSHA''s base is the legal default and every other rate is converted to it by the engine", "The FAR, on 100,000,000 hours, because the engine takes IOGP''s definition; every other rate is quoted on more than one base", "The PSE rate, on 1,000,000 hours, because API RP 754 names one base and the engine rejects every other base for it", "The severity rate, on 200,000 hours, because ANSI Z16.1 fixed its base and the engine follows that standard exactly"]'::jsonb, 1, '`fatalAccidentRate` takes no base argument; its basis reads 100000000 and IOGP safety performance indicators, FAR. Other bodies frame a fatal rate differently, per worker-year or per working lifetime, so a FAR quoted from elsewhere needs its definition checked. Every other function requires a named base and refuses a missing one, so the engine never guesses. There is no default base. The PSE rate accepts 200,000 or 1,000,000, and the severity rate takes a required base with no ANSI Z16.1 time charges added.'),
  ('safetystats', 'advanced', 'final', null, 28, 'What does pooling five years of IOGP data into one observed FAR buy, and what does it cost?', '["More fatalities under one figure, so it is steadier; the price is that a real change shows only slowly, diluted by earlier years", "An exact rate with no scatter, since five years of fatalities remove the count uncertainty of any single year altogether", "A figure that tracks the most recent year closely, since the latest year always carries the largest share of the hours", "A fairer weighting of the years, since pooling gives each of the five years an equal fifth of the published figure"]'::jsonb, 0, 'A single year''s observed FAR rests on a few dozen fatalities and moves; pooling steadies it, and 0.826095 hides the 2022 peak of 1.279566. More events shrink the uncertainty without removing it. The latest year carries the largest share on this series, 4158877000 hours, and still shares the figure with four others. Pooling weights by hours; equal fifths is the mean of the yearly rates, 0.833228.'),
  ('safetystats', 'advanced', 'final', null, 29, 'A report divides all 13 of AMUKPE''s site recordables by the company''s 846200 hours alone. What does that do to the rate?', '["It inflates it: the count includes contractors whose hours are left out, so the rate describes no workforce", "It gives the fair company rate, since the company is responsible for every event that is recorded on its site", "It deflates it, since the contractors'' events are spread thinly over the company''s hours and so count for less", "It gives the fair site rate, since company hours are the only hours an operator can verify for itself"]'::jsonb, 0, 'Events and hours must describe the same workforce, both in or both out. This is the opposite mismatch to dividing company events by everyone''s hours, and it errs the other way, upward. The fair company rate is 4 events over 846200 hours, 0.945403, and the fair site rate is 13 over 2238950, 1.161259. Either direction of mismatch breaks the rate.'),
  ('safetystats', 'advanced', 'final', null, 30, 'Why does AMUKPE''s site rate of 1.161259 sit closer to the contractors'' own rate than to the company''s 0.945403?', '["The contractors recorded more events, 9 of 13, and a pooled rate weights each group by its share of the events", "The site rate is the mean of the two groups'' rates, and the mean always sits closer to the higher of the two group rates", "The contractors'' rate is closer to IOGP''s, and a site rate is pulled toward the published benchmark for the year", "The contractors worked most of the site''s hours, 1392750 of 2238950, so they carry most of the weight in the pooled rate"]'::jsonb, 3, 'A pooled rate is a weighted average of the group rates with hours as the weights, so the group with most of the hours dominates. The contractors worked 1392750 of the 2238950 hours. The weights are hours, and the event count is what is being averaged. The mean of the two rates would weight the groups equally. No benchmark enters a pooled rate.'),
  ('safetystats', 'advanced', 'final', null, 31, 'After 2 of AMUKPE''s recordables are reclassified the site rate is 0.982603. How many further cases would need to move to first aid to bring it below the company-only 0.945403?', '["None, since 0.982603 is already below the company-only figure of 0.945403 on these hours", "Two more, since the rate falls by the same step each time and one step is not quite enough", "One more, taking the count to 10 on the same 2238950 hours", "Three more, since the fall must also clear the rate of 1.161259 recorded before the review"]'::jsonb, 2, 'The company-only rate on the site''s hours corresponds to a count between 10 and 11, so 11 cases sit above it and 10 below. One more relabelling reverses the comparison with no change on site, which is why a note reports every reclassification. 0.982603 is above 0.945403. The pre-review 1.161259 is not the target in the question.'),
  ('safetystats', 'advanced', 'final', null, 32, 'A site launches a programme after its worst quarter, and the next quarter comes in better. What should the note say before crediting the programme?', '["That the programme worked, since a better quarter straight after the launch is the most direct evidence a note can offer", "That the programme failed, since a real programme would show its effect in the worst quarter itself before the launch date", "Nothing about the timing, since a reader is best served by the figures alone and the launch date is an internal matter", "That a quarter picked for being the worst is likely to be followed by a better one even with no change, and compare whole fixed periods"]'::jsonb, 3, 'A period chosen because it was extreme is followed by a more ordinary one: partly because chance made it extreme, or because a one-off cause does not recur. Either way the fall arrives with no programme. The comparison that counts fixes the periods before the data are read, and the note says the baseline was the peak. Nothing launched after a quarter can act on that quarter.'),
  ('safetystats', 'advanced', 'final', null, 33, 'In KWALE''s mean of site rates, what weight does the jetty carry, and what weight in the pooled rate?', '["One third, 0.333333, in the mean of rates, and its share of the hours, 0.024805, in the pooled rate", "Its share of the hours, 0.024805, in both, since each of the two methods weights a site by its exposure", "One third in both, since the pooled rate and the mean of rates weight all three sites exactly the same", "Its share of the events, 1 of 12, in the pooled rate, and one third in the mean of site rates"]'::jsonb, 0, 'The mean of rates gives each of the three sites the same weight whatever its hours. The pooled rate weights each site by its share of the hours, and the jetty''s is 61480 over 2478540, which is 0.024805. The pooled rate is the rate of the whole workforce; the mean weights a jetty crew like a flow station. Events are what is averaged, and hours are the weights.'),
  ('safetystats', 'advanced', 'final', null, 34, 'Mean of rates over pooled figure: KWALE 1.754760 over 0.968312, AKASO''s first window 2.026485 over 1.208038, EGBEMA 3.202958 over 2.893273, IOGP 0.833228 over 0.826095. Which ratio is smallest, and why?', '["IOGP''s, because no year''s hours are a tiny fraction of another''s, so the equal weights differ little from the hours", "KWALE''s, because its three sites give the fewest periods to average, and fewer periods to average always narrow the gap", "EGBEMA''s, because a u-chart centre is exempt from the mean-of-rates mistake by the way the whole of the chart is drawn", "AKASO''s, because its shutdown month is left out of the mean, which pulls its mean toward its rolling rate"]'::jsonb, 0, 'The gap depends on how uneven the exposures are. IOGP''s years run from 2544201000 to 4158877000 hours, so equal weights are close to the hours; KWALE''s jetty carries 0.024805 of the hours and a third of the mean, which is why KWALE''s ratio is printed as 1.812185. EGBEMA''s thin month 3 opens a real gap too. Leaving out a no-hours period is correct and does not close AKASO''s gap, which comes from the short month.'),
  ('safetystats', 'advanced', 'final', null, 35, 'A corporate dashboard averages the TRIRs of its five business units, one of which is a small office. What does the Expert tier say about the result?', '["It is sound, since each business unit is a separate report and deserves an equal share of the group''s published figure", "It is sound once every unit uses the same base, since the base is the only thing that the averaging of rates can distort", "It is the mean-of-rates mistake one level up: the small office gets a full vote, and the figure can sit anywhere", "It is conservative, since an average of rates always sits above the pooled rate and so errs toward caution"]'::jsonb, 2, 'Small units with high rates, thin months and minor sites all carry a full vote in a mean. The group rate is sum then divide, which needs every unit''s counts and hours defined the same way. A shared base is necessary for any combination and does not repair the weighting. The mean sat above the pooled figure on every stream in this course, and that direction is a property of those streams.'),
  ('safetystats', 'advanced', 'final', null, 36, 'Month 8''s cause was found and recorded. What does the revision part of EGBEMA''s monitoring note say?', '["That month 8 and month 3 were set aside, since both readings were high, giving a cleaner and lower revised centre line", "That no revision was made, since a revised chart can only be drawn once the next year''s data have arrived", "That month 8 was set aside on that cause, the revised centre is 2.389523, and the revised chart flags no month", "That the limits were narrowed to 2 sigma, since a revised chart is always drawn on a narrower band than the first"]'::jsonb, 2, 'The revision part says whether the chart was redrawn, which months were set aside and the cause for each. With month 8''s cause found, the revised centre is 2.389523 and nothing is flagged, both results the engine returned. Month 3 had no cause, and a high reading is not one. Revision redraws the same 3 sigma chart on the months kept, as soon as the cause is found.'),
  ('safetystats', 'advanced', 'final', null, 37, 'A draft of EGBEMA''s before-and-after section reads: ratio 1.028627, p-value 1.000000. What else must it state?', '["Nothing more, since the ratio and the p-value together are the full result of the conditional exact test for the two periods", "The minlike p-value beside the central one, since a reader must see both conventions before judging whether the change is real or not", "The mean of the monthly rates on each side, since the rate ratio needs the average monthly rate to be read by a manager", "The intervention month, the months on each side, any month set aside, the counts and hours, and the interval 0.607952 to 1.755328"]'::jsonb, 3, 'A before-and-after claim says which months it used and why: months 1 to 6 against 7 to 12, the intervention at month 7, any month set aside with its cause, 35 events in 2389010 hours against 28 in 1965920, and the interval. The interval is what shows that large effects either way remain possible. The engine''s convention is central. Rates on each side are pooled, and a mean of monthly rates is the wrong figure.'),
  ('safetystats', 'advanced', 'final', null, 38, 'A caller asks `pseRate` for a Tier 1 rate on the 100,000,000 hour base. What comes back?', '["A rate per 100,000,000 hours, since the FAR base is accepted by every rate function in the engine without exception", "It is refused. The field named is `base`, and the engine''s message reads: base must be 200,000 or 1,000,000 for an API RP 754 PSE rate", "A refusal naming `tier`, since the FAR base is reserved for fatalities and so cannot carry any API RP 754 process safety event tier", "A rate converted to the 200,000 hour base, since the engine quietly rescales an unsupported base to the OSHA default before it rates the count"]'::jsonb, 1, 'API RP 754 rates sit on the 200,000 or 1,000,000 base, consistent with the basis for the company''s occupational injury rate, and the engine refuses the FAR base for a PSE rate. The refusal names the base field and carries no number. The engine never rescales a base and has no default one.'),
  ('safetystats', 'advanced', 'final', null, 39, 'On review, one of UGHELLI''s 4 Tier 2 events is proposed for reclassification as Tier 1. What must be seen before accepting it, and why can the engine not see it?', '["The engine''s own Tier check on the release, which it runs whenever a PSE count changes from one call to the next", "The new Tier 1 rate from `pseRate`, since a rate the engine accepts has already been classified correctly by it", "The days lost in the event, since the engine classifies a release as Tier 1 when its severity rate passes a set threshold", "The classification of the release against API RP 754''s threshold quantities, which are licensed and are not in the engine"]'::jsonb, 3, 'The tier is an input: the engine rates a count it is given and cannot classify a release, because the threshold quantity tables are licensed content absent from the engine, the golden and this course. It keeps nothing between calls, a rate it returns says nothing about the classification behind it, and it never classifies from days lost.'),
  ('safetystats', 'advanced', 'final', null, 40, 'The engine tables 22 refusals across 9 functions. What do they have in common?', '["Each is a warning attached to a returned rate, so the caller receives a number together with a note of what was wrong with it", "Each is about the shape of an input, such as a fraction, zero hours, a missing base or a tier of 3; none refuses a wrong classification", "Each is about a figure outside a plausible range, such as a rate above the IOGP benchmark or a count far above its expected value", "Each names the function that failed and leaves the offending field unnamed, so the caller has to search the inputs for the cause"]'::jsonb, 1, 'A refusal carries no number and names the field, with the engine''s message verbatim. Every one concerns the form of what was passed. Nothing in the engine refuses a count that was classified wrongly, and it carries no benchmark rates to judge plausibility against. That is why the classification questions belong to the analyst and the note.'),
  ('safetystats', 'advanced', 'final', null, 41, 'Why does the Expert tier want the engine''s central p-value, and not a minlike one, in a note that also quotes the rate-ratio interval?', '["The minlike p-value is always larger than the central one, so a note that uses it would understate every change it reports", "The central p-value is the convention of R''s poisson.test and of scipy, so a reader can check the engine''s figure directly", "The central p-value falls below 0.05 exactly when the interval excludes 1 on all 399 comparisons swept; the minlike one disagrees on 14", "The rate-ratio interval is computed from the p-value, so any p-value convention yields an interval that agrees with it"]'::jsonb, 2, 'The engine uses the central convention because it is the test the Clopper-Pearson interval inverts, and the course''s sweep over 399 UTOROGU comparisons confirms the agreement. On UTOROGU itself the minlike value, 0.025879, is smaller than the central 0.051759 and disagrees with an interval that includes 1. Minlike is the convention of R and scipy, which is why a reader may see a different number there. The interval is computed on its own.'),
  ('safetystats', 'advanced', 'final', null, 42, 'A monitoring note says only: no signals this year. What must it add for the reader to judge that claim?', '["What the chart could have seen: the exposure behind each point, any floored lower limits, and the thinnest month''s limit", "Nothing, since a year with no signals has shown the process was stable at every exposure the chart covered", "The mean of the monthly rates, since a quiet chart is best summarised for a reader by the average of its monthly readings", "A 2 sigma redraw, since a chart that flags nothing at 3 sigma must be narrowed until it shows at least one flagged month on it"]'::jsonb, 0, 'A quiet chart can be a chart with too little exposure per point to see anything, and floored lower limits mean it could never have found a fall. Naming the thin months and their limits tells the reader how strong the quiet is. The pooled rate with its interval summarises the year. Narrowing a band after seeing the chart chooses the band to make a flag.');
